/* ==================== Script 700 id="amiyo-ls-step05" ==================== */
/* Layer Studio step 5: creative frames. Film strip (sprocket holes), Camcorder viewfinder (blinking REC, live timecode, corner brackets),
   Scrapbook (paper border with tape) and Neon (glowing line). They appear in the Device frame list in Layer Studio. */
(function(){"use strict";
var LS=window.AMIYO_LS; if(!LS||!LS.frames||LS.frames5) return; LS.frames5=true;
[["film","Film strip"],["viewfinder","Viewfinder"],["scrap","Scrapbook"],["neon","Neon"]].forEach(function(x){ LS.frames.push(x); });
var NEON={black:"#ff5500",white:"#ffffff",silver:"#ffbe9e",gold:"#ffb300",blue:"#ff9f6f"};
function k(p){ return (p.frameSize==null?50:+p.frameSize)/50; }
LS.padFns.push(function(p,dw,dh){ var f=p.frame, mn=Math.min(dw,dh), kk=k(p), b;
  if(f==="film"){ b=mn*.13*kk; return {l:b,r:b,t:b*.28,b:b*.28}; }
  if(f==="scrap"){ b=mn*.045*kk; return {l:b,t:b,r:b,b:b*1.9}; }
  if(f==="neon"){ b=mn*.03*kk; return {l:b,t:b,r:b,b:b}; }
  return null; });
function rr(g,x,y,w,h,r){ r=Math.max(0,Math.min(r,w/2,h/2)); g.moveTo(x+r,y); g.arcTo(x+w,y,x+w,y+h,r); g.arcTo(x+w,y+h,x,y+h,r); g.arcTo(x,y+h,x,y,r); g.arcTo(x,y,x+w,y,r); g.closePath(); }
function tc(t){ t=Math.max(0,t||0); var f=Math.floor((t%1)*25), s=Math.floor(t)%60, m=Math.floor(t/60)%60, h=Math.floor(t/3600); function z(n){ return (n<10?"0":"")+n; } return z(h)+":"+z(m)+":"+z(s)+":"+z(f); }
LS.decor.push(function(g,i){ var p=i.p, f=p.frame, s=i.s, mn=Math.min(i.dw,i.dh), kk=k(p), px=i.PL, py=i.PT, pw=i.fw, ph=i.fh, light=(p.frameColor==="white"||p.frameColor==="silver");
  if(f==="film"){ var b=mn*.13*kk*s, vb=b*.28; g.beginPath(); g.rect(px-b,py-vb,pw+2*b,ph+2*vb); g.rect(px,py,pw,ph); g.fillStyle=light?"#e9e6dd":"#121214"; g.fill("evenodd");
    var hw=b*.42, hh=b*.3, gap=b*.62, hole=light?"#2a2a2e":"#d9d4c8"; g.fillStyle=hole;
    for(var y=py+gap*.35;y<py+ph-hh*.5;y+=gap){ g.beginPath(); rr(g,px-b+(b-hw)/2,y,hw,hh,hh*.28); g.fill(); g.beginPath(); rr(g,px+pw+(b-hw)/2,y,hw,hh,hh*.28); g.fill(); } }
  else if(f==="viewfinder"){ var m=mn*.05*s, L=mn*.07*s, lw=Math.max(1.5,mn*.004*s), fs=Math.max(9,mn*.034*s); g.strokeStyle="#ffffff"; g.lineWidth=lw; g.lineCap="square"; g.globalAlpha=.92;
    [[px+m,py+m,1,1],[px+pw-m,py+m,-1,1],[px+m,py+ph-m,1,-1],[px+pw-m,py+ph-m,-1,-1]].forEach(function(q){ g.beginPath(); g.moveTo(q[0]+q[2]*L,q[1]); g.lineTo(q[0],q[1]); g.lineTo(q[0],q[1]+q[3]*L); g.stroke(); });
    var cx=px+pw/2, cy=py+ph/2, cr=L*.5; g.beginPath(); g.moveTo(cx-cr,cy); g.lineTo(cx+cr,cy); g.moveTo(cx,cy-cr); g.lineTo(cx,cy+cr); g.stroke();
    var t=(typeof currentTime==="number")?currentTime:0; g.font="700 "+fs+"px ui-monospace,Menlo,monospace"; g.textBaseline="middle"; g.fillStyle="#fff"; g.shadowColor="rgba(0,0,0,.7)"; g.shadowBlur=fs*.3;
    if(Math.floor(t*2)%2===0){ g.fillStyle="#ff3b30"; g.beginPath(); g.arc(px+m+fs*.4,py+m+L*.62,fs*.34,0,Math.PI*2); g.fill(); }
    g.fillStyle="#fff"; g.textAlign="left"; g.fillText("REC",px+m+fs*1.1,py+m+L*.62); g.fillText(tc(t),px+m,py+ph-m-L*.62);
    g.textAlign="right"; g.fillText("HD",px+pw-m,py+m+L*.62); var bx=px+pw-m-fs*2.4, by=py+ph-m-L*.62-fs*.4; g.strokeRect(bx,by,fs*1.7,fs*.8); g.fillRect(bx+fs*1.7,by+fs*.22,fs*.15,fs*.36); g.fillRect(bx+fs*.12,by+fs*.12,fs*1.0,fs*.56); g.globalAlpha=1; }
  else if(f==="scrap"){ var bt=mn*.045*kk*s; g.beginPath(); g.rect(px-bt,py-bt,pw+2*bt,ph+bt*2.9); g.rect(px,py,pw,ph); g.fillStyle=p.frameColor==="black"?"#202024":(p.frameColor==="gold"?"#f2dfae":"#f6f1e4"); g.fill("evenodd");
    g.fillStyle="rgba(255,228,140,.78)"; [[px+pw*.08,py-bt*.2,-.35],[px+pw*.92,py-bt*.2,.35]].forEach(function(q){ g.save(); g.translate(q[0],q[1]); g.rotate(q[2]); g.fillRect(-bt*1.5,-bt*.55,bt*3,bt*1.1); g.restore(); }); }
  else if(f==="neon"){ var c=NEON[p.frameColor]||NEON.black, bt3=mn*.03*kk*s, w=Math.max(2,bt3*.35); g.strokeStyle=c; g.lineWidth=w; g.lineJoin="round"; g.shadowColor=c; g.shadowBlur=bt3*.9;
    g.beginPath(); rr(g,px-bt3*.45,py-bt3*.45,pw+bt3*.9,ph+bt3*.9,bt3*.7); g.stroke(); g.stroke(); g.shadowBlur=0; g.strokeStyle="#ffffff"; g.globalAlpha=.75; g.lineWidth=w*.35; g.stroke(); g.globalAlpha=1; } });
try{ window.AMIYO_EDITOR_BUILD="ls-step05-creative-frames"; }catch(e){}
})();

