/* ==================== Script 701 id="amiyo-ls-step06" ==================== */
/* Layer Studio step 6: gradient borders. A multi-colour outline that follows the layer's shape (circle, heart, star...).
   Choose a colour set, set the width and angle, and turn on Spin to make the colours rotate while the video plays.
   Draws into the layer itself, so it tilts and pins together with the video. Works with a device frame too. */
(function(){"use strict";
var LS=window.AMIYO_LS; if(!LS||!LS.padFns||LS.gb) return; LS.gb=true;
LS.def("gbWidth",{label:"Gradient border",min:0,max:40,step:.5,unit:"",group:"Gradient border"});
LS.def("gbAngle",{label:"Angle",min:0,max:360,unit:"°",group:"Gradient border"});
LS.def("gbSpin",{label:"Spin speed",min:-360,max:360,unit:"°/s",group:"Gradient border"});
var SETS=[["sunset","Sunset",["#ff512f","#f09819","#ffd200"]],["ocean","Ocean",["#ff5500","#ff5500"]],["rainbow","Rainbow",["#ff3b30","#ff9500","#ffd60a","#34c759","#ff5c0a","#bf5af2","#ff3b30"]],["pink","Pink-violet",["#ff4ecd","#ff925c"]],["gold","Gold",["#fff1a8","#d4a017","#fff1a8"]],["mint","Mint",["#38ef7d","#11998e"]]];
LS.gbSets=SETS;
LS.meshTests.push(function(p){ return +p.gbWidth>0; });
LS.padFns.push(function(p){ var w=+p.gbWidth||0; if(w<=0) return null; var W=(window.canvas&&canvas.width)||1920, e=w*W/1000*.7+3; return {l:e,t:e,r:e,b:e}; });
function cols(p){ return (Array.isArray(p.gbColors)&&p.gbColors.length>=2)?p.gbColors:SETS[0][2]; }
LS.decor.push(function(g,i){ var p=i.p, w=+p.gbWidth||0; if(w<=0) return; var W=(window.canvas&&canvas.width)||1920, lw=Math.max(1,w*W/1000)*i.s, c=i.clip, m=c&&c.mask;
  var t=(typeof currentTime==="number")?currentTime:0, ang=((+p.gbAngle||0)+(+p.gbSpin||0)*t)*Math.PI/180, cx=i.PL+i.fw/2, cy=i.PT+i.fh/2, r=Math.hypot(i.fw,i.fh)/2, dx=Math.cos(ang)*r, dy=Math.sin(ang)*r;
  var gr=g.createLinearGradient(cx-dx,cy-dy,cx+dx,cy+dy), cl=cols(p); cl.forEach(function(col,n){ gr.addColorStop(n/(cl.length-1),col); });
  g.lineWidth=lw; g.lineJoin="round"; g.strokeStyle=gr;
  if(m&&m.enabled&&window.amiyoShapePath){ window.amiyoShapePath(g,m.shape,i.PL+(m.x==null?.5:m.x)*i.fw,i.PT+(m.y==null?.5:m.y)*i.fh,(m.w==null?1:m.w)*i.fw,(m.h==null?1:m.h)*i.fh); }
  else { g.beginPath(); g.rect(i.PL,i.PT,i.fw,i.fh); }
  g.stroke(); });
LS.sections.push({id:"s6",render:function(c){ var cur=(c.ls&&c.ls.gbColors)||null, sel=cur?JSON.stringify(cur):"";
  var h='<h5>Border colours</h5><div class="chips">'+SETS.map(function(x){ var on=sel===JSON.stringify(x[2]); return '<button data-s="s6" data-a="set:'+x[0]+'" class="'+(on?"on":"")+'" style="background-image:linear-gradient(90deg,'+x[2].join(",")+');color:#111;font-weight:700;text-shadow:0 0 3px #fff8">'+x[1]+'</button>'; }).join("")+'</div>';
  var a=(cur&&cur[0])||SETS[0][2][0], b=(cur&&cur[cur.length-1])||SETS[0][2][SETS[0][2].length-1];
  h+='<div class="r" style="grid-template-columns:78px 1fr 1fr"><span>Own colours</span><input type="color" data-gc="0" value="'+a.slice(0,7)+'" aria-label="First colour"><input type="color" data-gc="1" value="'+b.slice(0,7)+'" aria-label="Second colour"></div>'; return h; },
  click:function(a){ var t=a.split(":"); var set=SETS.find(function(x){ return x[0]===t[1]; }); if(!set) return; LS.edit("Gradient border colours",function(c,ls){ ls.gbColors=set[2].slice(); if(!(+ls.gbWidth>0)) ls.gbWidth=8; }); }});
var el=LS.ensure(); el.addEventListener("change",function(e){ var t=e.target; if(!t.dataset||t.dataset.gc==null) return; var c=LS.target(); if(!c) return; var q=t.parentNode.querySelectorAll("input[type=color]");
  LS.edit("Gradient border colours",function(c2,ls){ ls.gbColors=[q[0].value,q[1].value]; if(!(+ls.gbWidth>0)) ls.gbWidth=8; }); LS.paint(); });
window.AMIYO_PIPX.add({id:"ls_gb0",group:"Layer Studio",label:"Remove gradient border",needs:undefined,run:function(){ var c=LS.target(); if(!c||!c.ls||!(+c.ls.gbWidth>0)){ window.AMIYO_PIPX.toast("No gradient border here"); return; } window.AMIYO_PIPX.change("Remove gradient border",function(){ delete c.ls.gbWidth; delete c.ls.gbSpin; delete c.ls.gbAngle; delete c.ls.gbColors; }); LS.paint(); }});
try{ window.AMIYO_EDITOR_BUILD="ls-step06-gradient-border"; }catch(e){}
})();

