  if(cur.width!==w||cur.height!==h){ cur.width=w; cur.height=h; } var c=cur.getContext("2d"); c.setTransform(1,0,0,1,0,0); c.globalCompositeOperation="source-over"; c.globalAlpha=1; c.clearRect(0,0,w,h); c.drawImage(S.cv,0,0);
  if(vh>0){ g.clearRect(0,0,w,h); g.filter="contrast("+(1+.12*vh)+") saturate("+(1+.35*vh)+") blur("+(vh*1.4)+"px)"; g.drawImage(cur,0,0); g.filter="none"; g.globalAlpha=.55; g.drawImage(cur,0,0); g.globalAlpha=1; c.clearRect(0,0,w,h); c.drawImage(S.cv,0,0); }
  if(gl>0&&burst){ var n=2+Math.floor(gl*9); for(var i=0;i<n;i++){ var sy=Math.floor(R()*h), sh=Math.max(2,Math.floor((.01+R()*.1)*h)), dx=Math.round((R()-.5)*2*gl*.2*w); g.clearRect(0,sy,w,sh); g.drawImage(cur,0,sy,w,sh,dx,sy,w,sh); } }
