function esc(s){ return LS.esc(s); }
function html(){ var R=rows(), fx=R.filter(function(r){ return r.sum.list.length; }), heavy=R.filter(function(r){ return r.sum.load==="heavy"; }), tot=fx.reduce(function(a,r){ return a+r.sum.cost; },0);
  var h='<div style="font:13px system-ui;color:#f1ece2"><div style="margin-bottom:8px">'+R.length+' video layer'+(R.length===1?"":"s")+' · <b>'+fx.length+'</b> with Layer Studio effects · '+(heavy.length?'<b style="color:#ff8a5c">'+heavy.length+' heavy</b>':"none heavy")+'</div>';
  if(heavy.length||tot>14) h+='<div style="background:#2a1d14;border:1px solid #6b3b1f;border-radius:8px;padding:6px 8px;margin-bottom:8px;color:#ffc9a8">Heavy layers can make playback stutter. Export is still correct, just slower. Try turning off echo, VHS or 3D on layers you do not need.</div>';
  if(!R.length) h+='<div>No video layers yet.</div>';
  R.forEach(function(r){ var s=r.sum, col=s.load==="heavy"?"#ff8a5c":s.load==="medium"?"#ffb454":"#8fd19a";
    h+='<div style="border:1px solid #302c26;border-radius:10px;padding:7px 9px;margin:5px 0;background:#14120f"><div style="display:flex;justify-content:space-between;gap:8px"><b>'+esc(r.name)+'</b><span style="color:#8f8777">'+esc(r.track)+' · '+r.role+' · '+(Math.round(r.c.start*10)/10)+'s</span></div>'+
    '<div style="color:#bdb5a5;margin:3px 0">'+(s.list.length?esc(s.list.join(", "))+' <span style="color:'+col+'">· '+s.load+'</span>':'No Layer Studio effects')+'</div>'+
    '<div style="display:flex;gap:6px;flex-wrap:wrap"><button type="button" data-lsr="sel:'+esc(r.c.id)+'">Go to layer</button>'+(s.list.length?'<button type="button" data-lsr="rst:'+esc(r.c.id)+'">Reset</button>':"")+'</div></div>'; });
  h+='<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px"><button type="button" data-lsr="all">Reset ALL layers</button><button type="button" data-lsr="copy">Copy report text</button></div></div>'; return h; }
LS.reportText=function(){ var L=["Layer Studio report"]; rows().forEach(function(r){ L.push("- "+r.name+" ("+r.track+", "+r.role+"): "+(r.sum.list.join(", ")||"no effects")+(r.sum.list.length?" ["+r.sum.load+"]":"")); }); return L.join("\n"); };
var armed=0;
