  function paint(b){ var on=document.body.classList.contains("ml-more"); b.textContent=on?"Less \u25B4":"More \u25BE"; b.setAttribute("aria-expanded",on?"true":"false"); b.title=on?"Hide Select several and Find duplicates":"Show Select several and Find duplicates"; }
