/* ==================== Script 718 id="amiyo-s74-tour-js" ==================== */
(function(){ try{
  function vis(e){ if(!e) return false; var r=e.getBoundingClientRect(); return r.width>8&&r.height>8&&getComputedStyle(e).visibility!=="hidden"&&r.bottom>0&&r.top<innerHeight; }
  function proBox(){ var hs=document.querySelectorAll("h3"); for(var i=0;i<hs.length;i++) if(/Professional Editing/.test(hs[i].textContent)&&vis(hs[i].parentElement)) return hs[i].parentElement; return null; }
  var STEPS=[
    ["Add your media","Import videos, images and audio here. Everything stays on this device.",function(){ return document.getElementById("importBtn"); }],
    ["The preview","Your edit plays here. Use Play, Frame and Fit above it.",function(){ return document.getElementById("previewCanvas"); }],
    ["The timeline","Drag clips onto tracks. Press S to split at the playhead and Delete to remove a clip.",function(){ return document.getElementById("timelineScroll"); }],
    ["Professional tools","Trim, speed, markers and more. Search for a tool by name, or pin your favourites to Quick.",proBox],
    ["Picture-in-picture","Select a video, then use PiP Studio here: add videos on top of it, pick a shape, place it, and set when it plays in the Timing tab.",function(){ var g=document.getElementById("ppGroup"); return g&&vis(g)?g:null; }],
    ["PiP+ tools","More tools for videos on top of videos: layouts, align, presets and more. Every change can be undone.",function(){ return document.getElementById("pipxBtn"); }],
    ["Export","When you are happy, export your video from here.",function(){ return document.getElementById("exportBtn"); }]
  ];
  var spot,tip,list,i;
  function end(){ if(spot) spot.remove(); if(tip) tip.remove(); spot=tip=null; try{ localStorage.setItem("amiyo.tour.done","1"); }catch(e){} document.removeEventListener("keydown",key,true); window.removeEventListener("resize",place); }
  function key(e){ if(e.key==="Escape"){ end(); e.stopPropagation(); } else if(e.key==="ArrowRight"){ go(1); } else if(e.key==="ArrowLeft"){ go(-1); } }
  function place(){ if(!spot) return; var st=list[i], el=st.f(); if(!vis(el)) return;
    var r=el.getBoundingClientRect(), pad=4;
    spot.style.left=(r.left-pad)+"px"; spot.style.top=(r.top-pad)+"px"; spot.style.width=(r.width+pad*2)+"px"; spot.style.height=(r.height+pad*2)+"px";
    var tw=Math.min(300,innerWidth-24), th=tip.offsetHeight||130, x=Math.max(12,Math.min(innerWidth-tw-12,r.left)), y=r.bottom+14;
    if(y+th>innerHeight-12) y=r.top-th-14; if(y<12) y=Math.max(12,Math.min(innerHeight-th-12,r.top+12));
    if(r.width>innerWidth*.6&&r.height>innerHeight*.5){ y=r.top+r.height/2-th/2; x=r.left+r.width/2-tw/2; }
    tip.style.left=Math.max(12,x)+"px"; tip.style.top=y+"px"; }
  function render(){ var st=list[i], el=st.f(); try{ el.scrollIntoView({block:"nearest",inline:"nearest"}); }catch(e){}
    tip.innerHTML="<h4></h4><p></p><div class='tr'><span></span><button type='button' id='amTourSkip'>Skip</button>"+(i>0?"<button type='button' id='amTourBack'>Back</button>":"")+"<button type='button' class='go' id='amTourNext'></button></div>";
    tip.querySelector("h4").textContent=st.t; tip.querySelector("p").textContent=st.d; tip.querySelector("span").textContent=(i+1)+" of "+list.length;
    tip.querySelector("#amTourNext").textContent=i===list.length-1?"Done":"Next";
    tip.querySelector("#amTourSkip").onclick=end; tip.querySelector("#amTourNext").onclick=function(){ go(1); };
    var bk=tip.querySelector("#amTourBack"); if(bk) bk.onclick=function(){ go(-1); };
    place(); setTimeout(place,300); tip.querySelector("#amTourNext").focus(); }
  function go(d){ var n=i+d; while(n>=0&&n<list.length&&!vis(list[n].f())) n+=d; if(n>=list.length){ end(); return; } if(n<0) return; i=n; render(); }
  function start(){ end(); try{ var m=document.getElementById("modal"); }catch(e){}
    list=STEPS.map(function(s){ return {t:s[0],d:s[1],f:s[2]}; }).filter(function(s){ return vis(s.f()); });
    if(!list.length) return;
    spot=document.createElement("div"); spot.id="amTourSpot"; tip=document.createElement("div"); tip.id="amTourTip"; tip.setAttribute("role","dialog"); tip.setAttribute("aria-label","Quick tour");
    document.body.appendChild(spot); document.body.appendChild(tip); i=0; render();
    document.addEventListener("keydown",key,true); window.addEventListener("resize",place); }
  window.amiyoStartTour=start;
  function link(){ var dz=document.getElementById("welcomeDropzone"); if(!dz||document.getElementById("amTourLink")) return;
    var b=document.createElement("button"); b.type="button"; b.id="amTourLink"; b.className="amTourLink"; b.textContent="New here? Take a 30-second tour";
    b.addEventListener("click",function(e){ e.stopPropagation(); start(); }); dz.appendChild(b); }
  link(); setTimeout(link,1500); setTimeout(link,4000);
  try{ new MutationObserver(link).observe(document.body,{childList:true,subtree:true}); }catch(e){}
}catch(e){ window.__swl&&window.__swl(e); } })();

