/* ==================== Script 719 id="amiyo-s77-folder-drop" ==================== */
/* Step 13: dropping a whole folder used to import nothing (the browser hands over the folder itself as an empty "file"). The folder is now read, subfolders included, and every video, audio and image file inside is imported. */
(function(){ try{
  var OK=/\.(mp4|m4v|mov|webm|mkv|avi|ogv|mp3|wav|wave|m4a|m4b|aac|ogg|oga|flac|opus|wma|aiff?|aifc|amr|caf|weba|mka|jpe?g|png|gif|webp|bmp|avif|svg)$/i;
  function isMedia(f){ return /^(video|audio|image)\//.test(f.type||"")||OK.test(f.name||""); }
  function readAll(dir){ return new Promise(function(res){ var r=dir.createReader(), all=[]; (function next(){ r.readEntries(function(b){ if(!b.length) return res(all); all=all.concat([].slice.call(b)); next(); },function(){ res(all); }); })(); }); }
  function fileOf(en){ return new Promise(function(res){ en.file(function(f){ res(f); },function(){ res(null); }); }); }
  async function walk(en,out,depth){ if(!en||out.length>2000) return;
    if(en.isFile){ var f=await fileOf(en); if(f&&isMedia(f)){ try{ var _p=String(en.fullPath||"").replace(/^\//,""); if(_p.indexOf("/")>0) f.__amiyoRel=_p; }catch(_e){} out.push(f); } }
    else if(en.isDirectory&&depth<12){ var kids=await readAll(en); for(var i=0;i<kids.length;i++) await walk(kids[i],out,depth+1); } }
  window.amiyoCollectDropped=async function(entries){ var out=[]; for(var i=0;i<entries.length;i++) await walk(entries[i],out,0); out.sort(function(a,b){ return a.name<b.name?-1:a.name>b.name?1:0; }); return out; };
  document.addEventListener("drop",function(e){
    var dt=e.dataTransfer; if(!dt||!dt.items||!dt.items.length) return;
    var ents=[], hasDir=false;
    for(var i=0;i<dt.items.length;i++){ var it=dt.items[i]; if(it.kind!=="file") continue; var en=it.webkitGetAsEntry&&it.webkitGetAsEntry(); if(!en) continue; ents.push(en); if(en.isDirectory) hasDir=true; }
    if(!hasDir) return;                     /* plain files keep using the normal path */
    e.preventDefault(); e.stopPropagation();
    try{ var ov=document.getElementById("welcomeOverlay"); if(ov) ov.classList.remove("drag-over"); }catch(x){}
    var say=function(m){ try{ (window.toast||function(){})(m); }catch(x){} };
    say("Reading folder…");
    window.amiyoCollectDropped(ents).then(function(files){
      if(!files.length){ say("No video, audio or image files found in that folder."); return; }
      say("Importing "+files.length+" file"+(files.length===1?"":"s")+" from the folder…");
      return window.importFiles(files);
    }).catch(function(err){ say("Could not read that folder."); window.__swl&&window.__swl(err); });
  },true);
}catch(e){ window.__swl&&window.__swl(e); } })();

