/* ==================== Script 721 id="amiyo-editor-s79" ==================== */
/* Editor step 79: export upgrades.
   1) Sound on / No sound   2) Quality: smaller file · balanced · best (scales the bitrate of any size or preset)
   3) Save the current frame as a PNG (dialog + command palette)
   Also (in the exporter itself): a finished video is never thrown away because the browser could not preview it,
   the file check can no longer hang, and file names are cleaned of characters that break downloads. */
(function(){
  "use strict";
  var Q=[["Smaller file",.6],["Balanced",1],["Best quality",1.5]];
  window.__amiyoXMute=false; window.__amiyoXQ=1;
  function $(i){ return document.getElementById(i); }
  function toastS(m,ms){ try{ (window.toast||function(){})(m,ms||3000); }catch(e){ window.__swl&&window.__swl(e); } }
  window.amiyoSaveFrame=async function(){
    try{
      if(typeof viewCanvas==="undefined"||!viewCanvas.toBlob){ toastS("This browser cannot save a frame"); return; }
      await renderPreviewFrame();
      viewCanvas.toBlob(function(b){
        if(!b){ toastS("Could not save the frame"); return; }
        var s=Math.max(0,Math.floor(currentTime||0)), tc=[Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(function(n){ return String(n).padStart(2,"0"); }).join("-");
        var nm=String((project.metadata&&project.metadata.name)||"amiyo-edit").replace(/[\\\/:*?"<>|\u0000-\u001f]+/g,"-").trim()||"amiyo-edit";
        var u=URL.createObjectURL(b), a=document.createElement("a"); a.href=u; a.download=nm+"-frame-"+tc+".png"; document.body.appendChild(a); a.click(); a.remove();
        setTimeout(function(){ URL.revokeObjectURL(u); },8000); toastS("Frame saved as PNG ("+viewCanvas.width+"×"+viewCanvas.height+")");
      },"image/png");
    }catch(e){ toastS("Could not save the frame"); window.__swl&&window.__swl(e); }
  };
  function mark(box,pick){ [].slice.call(box.querySelectorAll(".chip")).forEach(function(c,i){ var on=pick(c,i); c.style.outline=on?"2px solid var(--accent)":"none"; c.setAttribute("aria-pressed",on?"true":"false"); }); }
  function inject(){
    var go=$("expGo"); if(!go||$("expExtra")) return;
    window.__amiyoXMute=false; window.__amiyoXQ=1;
    var box=document.createElement("div"); box.id="expExtra";
    box.innerHTML='<label class="field" style="margin-top:10px">Sound</label><div class="mini-row" id="expSound" role="group" aria-label="Sound"><button type="button" class="chip" data-m="0">Sound on</button><button type="button" class="chip" data-m="1">No sound</button></div>'+
      '<label class="field" style="margin-top:10px">Quality (file size)</label><div class="mini-row" id="expQual" role="group" aria-label="Quality">'+Q.map(function(q,i){ return '<button type="button" class="chip" data-q="'+q[1]+'" title="'+(i===0?"About 40% smaller, softer picture":i===2?"About 50% larger, cleaner picture":"Recommended")+'">'+q[0]+'</button>'; }).join("")+'</div>'+
      '<div class="mini-row" style="margin-top:10px"><button type="button" class="chip" id="expFrameBtn" title="Save the picture at the playhead as a PNG">Save this frame (PNG)</button></div>';
    var anchor=$("expSummary")||go.parentNode; anchor.parentNode.insertBefore(box,anchor);
    var s=$("expSound"), q=$("expQual");
    function paint(){ mark(s,function(c){ return (c.dataset.m==="1")===!!window.__amiyoXMute; }); mark(q,function(c){ return Number(c.dataset.q)===window.__amiyoXQ; }); }
    s.addEventListener("click",function(e){ var c=e.target.closest(".chip"); if(!c) return; window.__amiyoXMute=c.dataset.m==="1"; paint(); });
    q.addEventListener("click",function(e){ var c=e.target.closest(".chip"); if(!c) return; window.__amiyoXQ=Number(c.dataset.q)||1; paint(); });
    $("expFrameBtn").onclick=function(){ window.amiyoSaveFrame(); };
    paint();
  }
  var prev=window.openModal;
  window.openModal=function(title){
    var r=prev.apply(this,arguments);
    if(title==="Export video"){ try{ inject(); }catch(e){ try{ window.amiyoReportError&&window.amiyoReportError("Export options could not load",e,{quiet:true}); }catch(x){ window.__swl&&window.__swl(x); } } }
    return r;
  };
  var oc=window.commandList;
  if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Save current frame as PNG","amiyoSaveFrame()"]]); };
})();

