      info.textContent=r?("Exports "+tc(r.t0)+" – "+tc(r.t1)+" ("+tc(len)+" long) of the "+tc(full())+" edit."):"Exports the whole edit ("+tc(full())+").";
      var p=document.querySelector("#modalBody .x80-left > p b, #modalBody > p b"); if(p) p.textContent=tc(len).replace(/^(\d+):(\d\d).*$/,function(a,m,s){ return +m? m+" min "+(+s?(+s)+" s":"") : (+s)+" s"; });
