  "use strict";
  window.__amiyoXFps=0;
  var LIST=[0,24,25,30,50,60], NOTE={0:"Uses the project frame rate.",24:"Film look. Small files.",25:"PAL / European TV standard.",30:"Standard for phones and the web.",50:"Smooth motion (PAL sports). Needs a fast device.",60:"Smoothest motion. Needs a fast device and makes bigger files."};
