      var N=window.amiyoExportNow&&window.amiyoExportNow({autoRate:mode==="manual"}), a=N?N.vb:auto(), mb=a/1e6, qn=window.__amiyoXQ||1;   /* export step 10: follows the quality chip and a chosen preset, like the size lines */
      if(mode==="auto"){ $("expBrNote").textContent="Auto picks about "+mb.toFixed(1)+" Mbps"+(window.__amiyoPresetBps?" (from the preset)":(qn<1?" with Smaller file":qn>1?" with Best quality":""))+" for this size and frame rate. Use the Quality chips to go smaller or larger."; return; }
      var v=+R.value*1e6, ratio=v/a, tag=ratio<.5?"low: expect soft or blocky picture":ratio<.85?"on the low side":ratio<=1.6?"about right":"high: larger file, little visible gain";
