/* ==================== Script 731 id="amiyo-export-p11" ==================== */
/* Editor step 90 (export plan 11/20): where the file is saved.
   "Downloads" is the usual browser download. "Folder" lets you pick a folder once (Chrome, Edge and other browsers with the
   File System Access feature); finished files are then written straight into it with no download prompt, and a part-by-part
   export of a long video lands in one place. The folder is remembered; after a restart the browser asks you to allow it again when you press Start.
   Existing files are never overwritten (a " (2)" is added). If writing fails, the file is downloaded instead. */
(function(){
  "use strict";
  var MODE_KEY="amiyo_editor_out_mode", can=typeof window.showDirectoryPicker==="function";
  window.__amiyoWhere="";
  function $(i){ return document.getElementById(i); }
  function say(m,ms){ try{ window.toast(m,ms||4000); }catch(e){ window.__swl&&window.__swl(e); } }
  function mode(){ try{ return localStorage.getItem(MODE_KEY)==="dir"?"dir":"dl"; }catch(e){ return "dl"; } }
  function setMode(m){ try{ localStorage.setItem(MODE_KEY,m); }catch(e){ window.__swl&&window.__swl(e); } }
  /* the chosen folder handle lives in IndexedDB (it can be stored there, unlike in localStorage) */
  function db(){ return new Promise(function(res,rej){ var r=indexedDB.open("amiyo_export_out",1); r.onupgradeneeded=function(){ r.result.createObjectStore("kv"); }; r.onsuccess=function(){ res(r.result); }; r.onerror=function(){ rej(r.error); }; }); }
  function kv(op,val){ return db().then(function(d){ return new Promise(function(res,rej){ var tx=d.transaction("kv",op==="get"?"readonly":"readwrite"), s=tx.objectStore("kv"), q=op==="get"?s.get("dir"):(op==="set"?s.put(val,"dir"):s.delete("dir")); q.onsuccess=function(){ res(q.result); }; q.onerror=function(){ rej(q.error); }; }); }); }
  var handle=null;
  function perm(h,ask){ if(!h||!h.queryPermission) return Promise.resolve("denied"); return h.queryPermission({mode:"readwrite"}).then(function(p){ return (p==="granted"||!ask)?p:h.requestPermission({mode:"readwrite"}); }); }
  function uniqueName(dir,name){
    var dot=name.lastIndexOf("."), base=dot>0?name.slice(0,dot):name, ext=dot>0?name.slice(dot):"", n=1;
    function next(){ var cand=n===1?name:base+" ("+n+")"+ext; return dir.getFileHandle(cand).then(function(){ if(++n>99) throw new Error("too many copies"); return next(); },function(e){ if(e&&e.name==="NotFoundError") return cand; throw e; }); }
    return next();
  }
  window.amiyoSaveOut=function(blob,fname){
    window.__amiyoWhere=""; window.__amiyoSavedAs="";   /* step 5 (plan 2026-11): forget the last export's folder, so a fallback download is not reported as saved to the folder */
    if(mode()!=="dir"||!handle) return Promise.resolve(false);
    return perm(handle,true).then(function(p){ if(p!=="granted") throw new Error("permission"); return uniqueName(handle,fname); })
      .then(function(n){ return handle.getFileHandle(n,{create:true}).then(function(fh){ return fh.createWritable(); }).then(function(w){ return w.write(blob).then(function(){ return w.close(); }); }).then(function(){ window.__amiyoWhere=handle.name; window.__amiyoSavedAs=n; say("Saved "+n+" to “"+handle.name+"”"); return true; }); })
      .catch(function(e){ say((window.amiyoFolderWhy?window.amiyoFolderWhy(e,handle&&handle.name):"Could not write to the folder, so the file was downloaded instead."),8000); window.__swl&&window.__swl(e); return false; });
  };
  kv("get").then(function(h){ if(h) handle=h; }).catch(function(e){ window.__swl&&window.__swl(e); });
  function esc(x){ return String(x).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
  function inject(){
    var anchor=$("expNameTpl")||$("expName"); if(!anchor||$("expSaveTo")) return;
    var box=document.createElement("div"); box.id="expSaveTo"; box.style.marginTop="10px";
    if(!can){ box.innerHTML='<label class="field">Save to</label><div style="font-size:11px;color:var(--muted)">This browser saves finished videos to its Downloads folder.</div>'; anchor.parentNode.insertBefore(box,anchor.nextSibling); return; }
    box.innerHTML='<label class="field">Save to</label><div class="mini-row" id="expWhereRow" role="group" aria-label="Save to"><button type="button" class="chip" data-w="dl">Downloads</button><button type="button" class="chip" data-w="dir" id="expWhereDir"></button><button type="button" class="chip" data-w="pick" id="expWherePick">Change folder…</button></div>'+
      '<div id="expWhereNote" style="font-size:11px;color:var(--muted);margin-top:6px" aria-live="polite"></div>';
    anchor.parentNode.insertBefore(box,anchor.nextSibling);
    var row=$("expWhereRow"), note=$("expWhereNote");
    function paint(){
      var m=mode(), dirBtn=$("expWhereDir"), pk=$("expWherePick"); if(!dirBtn||!pk||!row.isConnected||!note) return; dirBtn.textContent=handle?("Folder: "+handle.name):"Choose folder…"; pk.hidden=!handle;
      [].slice.call(row.querySelectorAll('[data-w="dl"],[data-w="dir"]')).forEach(function(c){ var on=c.dataset.w===m&&(m==="dl"||!!handle); c.style.outline=on?"2px solid var(--accent)":"none"; c.setAttribute("aria-pressed",on?"true":"false"); });
      note.textContent=(m==="dir"&&handle)?"Files are written straight into “"+handle.name+"”. Nothing is overwritten; a number is added to a repeated name.":"Saved through the browser's normal download (usually your Downloads folder).";
    }
    function pick(){
      return window.showDirectoryPicker({mode:"readwrite",id:"amiyo-export"}).then(function(h){ handle=h; setMode("dir"); return kv("set",h).catch(function(e){ window.__swl&&window.__swl(e); }); }).then(paint)
        .catch(function(e){ if(e&&e.name!=="AbortError") say("Could not open that folder",4000); paint(); });
    }
    row.addEventListener("click",function(e){
      var c=e.target.closest(".chip"); if(!c) return;
      if(c.dataset.w==="dl"){ setMode("dl"); paint(); }
      else if(c.dataset.w==="pick"||!handle){ pick(); }
      else { setMode("dir"); paint(); perm(handle,true).then(function(p){ if(p!=="granted") say("Folder access was not allowed. Downloads will be used.",4500); }).catch(function(e){ window.__swl&&window.__swl(e); }); }
    });
    /* pressing Start is a click, so the browser can ask to re-allow a remembered folder right then */
    $("modalBody").addEventListener("click",function(e){ if(e.target&&e.target.id==="expGo"&&mode()==="dir"&&handle) perm(handle,true).catch(function(x){ window.__swl&&window.__swl(x); }); },true);
    kv("get").then(function(h){ if(h) handle=h; paint(); }).catch(function(){ paint(); });
    paint();
  }
  var prev=window.openModal;
  window.openModal=function(title){
    var r=prev.apply(this,arguments);
    if(title==="Export video"){ try{ inject(); }catch(e){ try{ window.amiyoReportError&&window.amiyoReportError("Save location could not load",e,{quiet:true}); }catch(x){ window.__swl&&window.__swl(x); } } }
    return r;
  };
})();

