/* ==================== Script 734 id="amiyo-v97-snap-js" ==================== */
(function(){
  var toast,tmr,last=null;
  function say(t){ try{
    if(!toast){toast=document.createElement('div');toast.id='amSnapToast';toast.setAttribute('role','status');toast.setAttribute('aria-live','polite');document.body.appendChild(toast);}
    toast.textContent=t;toast.classList.add('show');clearTimeout(tmr);tmr=setTimeout(function(){toast.classList.remove('show');},1400);}catch(e){} }
  function sync(announce){
    var b=document.getElementById('snapToggle'); if(!b) return;
    var on=b.classList.contains('tool-active');
    b.setAttribute('aria-pressed',on?'true':'false');
    b.title='Snapping '+(on?'ON':'OFF')+' - click to turn '+(on?'off':'on')+' (clips snap to edges and the playhead)';
    if(announce&&last!==null&&last!==on) say('Snapping '+(on?'ON':'OFF'));
    last=on;
  }
  function boot(){
    var b=document.getElementById('snapToggle'); if(!b){setTimeout(boot,500);return;}
    sync(false);
    new MutationObserver(function(){sync(true);}).observe(b,{attributes:true,attributeFilter:['class']});
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot); else boot();
})();

