/* ==================== Script 735 id="amiyo-v101-monitor-js" ==================== */
(function(){
  function get(k){try{return localStorage.getItem(k)==='1';}catch(e){return false;}}
  function put(k,v){try{localStorage.setItem(k,v?'1':'0');}catch(e){}}
  var safeOn=get('am_safe'),tcOn=get('am_tc'),safeEl,tcEl,raf=0,lastT=-1,sb,tb;
  function pad(n,l){n=String(n);while(n.length<(l||2))n='0'+n;return n;}
  function tc(t){var fps=Math.round((window.project&&project.settings&&+project.settings.fps)||30);if(!(fps>0))fps=30;
    var f=Math.round(t*fps),s=Math.floor(f/fps),ff=f-s*fps;return pad(Math.floor(s/3600))+':'+pad(Math.floor(s/60)%60)+':'+pad(s%60)+':'+pad(ff);}
  function loop(){raf=0;if(!tcOn)return;try{if(currentTime!==lastT){lastT=currentTime;tcEl.textContent=tc(currentTime);}}catch(e){}raf=requestAnimationFrame(loop);}
  function apply(){
    if(safeEl)safeEl.classList.toggle('on',safeOn); if(tcEl)tcEl.classList.toggle('on',tcOn);
    if(sb)sb.setAttribute('aria-pressed',safeOn?'true':'false'); if(tb)tb.setAttribute('aria-pressed',tcOn?'true':'false');
    if(tcOn&&!raf){lastT=-1;raf=requestAnimationFrame(loop);}
  }
  function mk(id,label,title,fn){var b=document.createElement('button');b.type='button';b.className='toolbtn';b.id=id;b.textContent=label;b.title=title;b.setAttribute('aria-label',title);b.setAttribute('aria-pressed','false');b.onclick=fn;return b;}
  function boot(){
    var shell=document.getElementById('canvasShell'),grid=document.getElementById('gridBtn');
    if(!shell||!grid){setTimeout(boot,500);return;}
    safeEl=document.createElement('div');safeEl.id='amSafeGuides';safeEl.setAttribute('aria-hidden','true');safeEl.innerHTML='<i class="a"></i><i class="t"></i><b></b>';
    tcEl=document.createElement('div');tcEl.id='amTcOverlay';tcEl.setAttribute('aria-hidden','true');tcEl.textContent='00:00:00:00';
    var ov=shell.querySelector('.preview-overlay')||shell;ov.appendChild(safeEl);ov.appendChild(tcEl);
    sb=mk('amSafeBtn','Safe','Safe margins: action-safe 90% and title-safe 80%',function(){safeOn=!safeOn;put('am_safe',safeOn);apply();});
    tb=mk('amTcBtn','TC','Timecode readout on the preview (not exported)',function(){tcOn=!tcOn;put('am_tc',tcOn);apply();});
    grid.parentNode.insertBefore(sb,grid.nextSibling);grid.parentNode.insertBefore(tb,sb.nextSibling);
    apply();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();

