/* ==================== Script 736 id="amiyo-v102-scrub-js" ==================== */
(function(){
  var bar,sl,last=-1,lastD=-1;
  function dur(){try{return Math.max(0.01,+getProjectDuration()||0.01);}catch(e){return 0.01;}}
  function fps(){try{var f=Math.round(+project.settings.fps);return f>0?f:30;}catch(e){return 30;}}
  function sync(){try{
    var d=dur(),t=currentTime; if(t===last&&d===lastD) return; last=t;lastD=d;
    sl.max=d; sl.value=t; sl.style.setProperty('--am-p',Math.min(100,Math.max(0,t/d*100))+'%');
    sl.setAttribute('aria-valuetext',t.toFixed(2)+' of '+d.toFixed(2)+' seconds');
  }catch(e){}}
  function go(t){try{setCurrentTime(Math.max(0,Math.min(dur(),t)));}catch(e){}}
  function btn(txt,title,fn){var b=document.createElement('button');b.type='button';b.textContent=txt;b.title=title;b.setAttribute('aria-label',title);b.onclick=fn;return b;}
  function boot(){
    var stage=document.querySelector('.preview-stage'); if(!stage||!stage.parentNode||typeof setCurrentTime!=='function'){setTimeout(boot,500);return;}
    bar=document.createElement('div');bar.id='amMonitorBar';
    sl=document.createElement('input');sl.type='range';sl.id='amScrub';sl.min=0;sl.step=0.01;sl.value=0;sl.setAttribute('aria-label','Scrub the program monitor');
    sl.title='Drag to scrub (Left/Right = 1 frame, Shift = 1 second)';
    sl.addEventListener('input',function(){go(+sl.value);});
    sl.addEventListener('keydown',function(e){
      if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();e.stopPropagation();var s=e.shiftKey?1:1/fps();go(currentTime+(e.key==='ArrowRight'?s:-s));}
      else if(e.key==='Home'){e.preventDefault();e.stopPropagation();go(0);} else if(e.key==='End'){e.preventDefault();e.stopPropagation();go(dur());}
    });
    bar.appendChild(btn('\u23EE','Go to start',function(){go(0);}));
    bar.appendChild(sl);
    bar.appendChild(btn('\u23ED','Go to end',function(){go(dur());}));
    stage.parentNode.insertBefore(bar,stage.nextSibling);
    setInterval(sync,80); sync();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();

