/* ==================== Script 737 id="amiyo-v104-meterscale-js" ==================== */
(function(){
  var marks=[[0,'0'],[-6,'-6'],[-18,'-18'],[-30,'-30'],[-48,'-48']];
  function build(){
    var m=document.getElementById('prMeter'); if(!m){setTimeout(build,500);return;}
    if(m.querySelector('.am-scale')) return;
    var s=document.createElement('div'); s.className='am-scale'; s.setAttribute('aria-hidden','true');
    marks.forEach(function(k){var e=document.createElement('span');e.textContent=k[1];e.style.top=((1-(k[0]+60)/60)*100)+'%';if(k[0]===0)e.className='top';s.appendChild(e);});
    m.appendChild(s);
    m.title='Master level, left and right, -60 to 0 dBFS. White ticks hold the peak, the red lamp lights on clipping. Click to reset.';
    m.setAttribute('aria-label','Master audio level meter');
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',build);else build();
})();

