  var DEB_LAUNCHER="#!/bin/sh\n# Amiyo Editor launcher: opens the editor as its own window (Chrome/Edge/Brave/Chromium), else Firefox, else the default browser\nURL=\"file:///opt/amiyo-editor/index.html\"\nfor b in google-chrome google-chrome-stable chromium chromium-browser microsoft-edge microsoft-edge-stable brave-browser vivaldi; do\n  if command -v \"$b\" >/dev/null 2>&1; then exec \"$b\" --app=\"$URL\" --class=AmiyoEditor; fi\ndone\nif command -v firefox >/dev/null 2>&1; then exec firefox \"$URL\"; fi\nif command -v xdg-open >/dev/null 2>&1; then exec xdg-open \"$URL\"; fi\necho \"No web browser found. Open this file in a browser: $URL\"\nexit 1\n";
