      var ct=dec.decode(cm["./control"].data);
      ["Package","Version","Architecture","Maintainer","Installed-Size","Description"].forEach(function(k){ if(!new RegExp("^"+k+": \\S","m").test(ct)) throw new Error("control field "+k+" is missing"); });
