    var labels={}; hl.forEach(function(l){ var m=/^:(\w+)/.exec(l); if(m) labels[m[1]]=1; });
    hl.forEach(function(l){ var m=/\bgoto\s+(\w+)/i.exec(l); if(m&&!labels[m[1]]) throw new Error("goto "+m[1]+" has no label"); });
    var pl=hl.filter(function(l){ return /^powershell /.test(l); });
    if(pl.length!==1||(pl[0].match(/"/g)||[]).length!==2) throw new Error("PowerShell line is malformed");
    checks.push("script layout");
    var ps=text.slice(iPS+11,iPE+2);
    if(/^:/m.test(ps)) throw new Error("installer program has a line that could be read as a label");
    ["GZipStream","SHA256","WriteAllBytes","CreateShortcut","Uninstall\\AmiyoEditor"].forEach(function(k){ if(ps.indexOf(k)<0) throw new Error("installer program is missing "+k); });
    var ob=(ps.match(/\{/g)||[]).length, cb=(ps.match(/\}/g)||[]).length, op=(ps.match(/\(/g)||[]).length, cp=(ps.match(/\)/g)||[]).length;
    if(ob!==cb||op!==cp) throw new Error("installer program has unbalanced brackets");
    checks.push("installer program");
