  var EXE_ARCH={
    x64:{file:"amiyo-editor-setup-x64.exe",bits:64,machine:0x8664,magic:0x20b,stubSha:"ee676a2abf4b6b0bebfc02a33995f4920a544a60973911adf0fcb7323ea03e1f",stub:""}
  };

  /* ---------- Windows .exe installers (steps 4 and 5) ---------- */
  /* A real Windows program (a small installer written in C, built for 64-bit and 32-bit Windows) is carried inside this page.
     The page appends the editor, its icon and a checksum to it and hands you the result as a normal setup .exe. The program
     checks its own contents, installs for the current user (no administrator), makes Start menu / desktop shortcuts, and adds
     an entry in Settings > Apps. Run it again with /uninstall to remove it, or /silent to skip all questions. */
  var EXE_FOOT=64;
  function hexBytes(h){ var o=new Uint8Array(h.length/2); for(var i=0;i<o.length;i++) o[i]=parseInt(h.substr(i*2,2),16); return o; }
