/* ==================== Script 746 id="amiyo-installers-final" ==================== */
(function(){
  "use strict";
  var A=window.AmiyoInstall; if(!A||A.recommend) return;
  /* ---------- Step 10: recommended installer for this computer ---------- */
  function detect(){
    var ua=(navigator.userAgent||"")+" "+(navigator.platform||""), os="", id="", note="";
    if(/Android|iPhone|iPad|iPod/i.test(ua)) return {os:"phone",id:"",note:"Phones and tablets do not need an installer: use the Install button in the top bar to add Amiyo Editor to your home screen."};
    if(/Win/i.test(ua)){ os="Windows"; id=(/Win64|x64|WOW64|ARM64/i.test(ua))?"exe64":"exe32"; note=id==="exe64"?"Windows (64-bit)":"Windows (32-bit)"; }
    else if(/Mac/i.test(ua)){ os="Mac"; id="app"; note="a Mac"; }
    else if(/Linux|X11|CrOS/i.test(ua)){ os="Linux"; id="sh"; note="Linux (the .sh works on every Linux; Debian, Ubuntu and Mint can also use the .deb)"; }
    return {os:os,id:id,note:note?("Your computer looks like "+note+"."):""};
  }
  A.recommend=detect;
  function css(){
    if(document.getElementById("amiRecCss")) return;
    var s=document.createElement("style"); s.id="amiRecCss";
    s.textContent="#amiInstBox .ai-rec{display:inline-block;margin-left:6px;padding:1px 7px;border-radius:99px;font:600 10px var(--font-mono,monospace);letter-spacing:.04em;text-transform:uppercase;background:var(--accent,#ff7a3d);color:#1a0c03;vertical-align:middle}#amiInstBox .ai-row.rec{border-color:var(--accent,#ff7a3d)}#amiInstBox .ai-yours{margin:10px 0 0;font-size:12px;color:var(--muted,#948a79)}";
    document.head.appendChild(s);
  }
  function decorate(back){
    var d=detect(); css();
    var list=back.querySelector("#amiInstList"); if(!list) return;
    if(!back.querySelector("#amiYours")&&d.note){ var p=document.createElement("div"); p.id="amiYours"; p.className="ai-yours"; p.textContent=d.note; list.parentNode.insertBefore(p,list); }
    var b=d.id&&list.querySelector('button[data-b="'+d.id+'"]'); if(!b) return;
    var row=b.parentNode; if(row.querySelector(".ai-rec")) return;
    row.className+=" rec"; var t=row.querySelector("b"); if(t){ var s=document.createElement("em"); s.className="ai-rec"; s.style.fontStyle="normal"; s.textContent="Recommended"; t.appendChild(s); }
  }
  function hook(back){
    var list=back.querySelector("#amiInstList"); if(!list||typeof MutationObserver==="undefined"){ decorate(back); return; }
    decorate(back); new MutationObserver(function(){ decorate(back); }).observe(list,{childList:true});
  }
  function watch(){ var b=document.getElementById("amiInstBack"); if(b){ hook(b); return true; } return false; }
  if(!watch()&&typeof MutationObserver!=="undefined"){ var mo=new MutationObserver(function(){ if(watch()) mo.disconnect(); }); mo.observe(document.body,{childList:true}); }
  A.step=126;
})();

