/* ==================== Script 747 id="amiyo-export-p12" ==================== */
/* Editor export plan 12/20: pre-export check (Premiere's "check before you render").
   A "Check" card in the Export dialog looks at the edit before you press Start and lists what would surprise you:
   missing media, black gaps on the picture, sound that would come out silent, hidden tracks that still hold clips, and zero-length clips.
   Green tick = fine. It only reads the project; it never changes it or blocks the export. It refreshes when you change any setting. */
(function(){
  "use strict";
  function $(i){ return document.getElementById(i); }
  function esc(x){ return String(x).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
  function tc(s){ s=Math.max(0,s||0); var m=Math.floor(s/60), x=s-m*60; return m+":"+(x<10?"0":"")+x.toFixed(1); }
  function have(a){
    if(!a) return false;
    var id=a.id; try{ if(typeof ASSET_BLOBS!=="undefined"&&ASSET_BLOBS.has(id)) return true; }catch(e){ window.__swl&&window.__swl(e); }
    return typeof a.fileData==="string"&&a.fileData.length>0 || typeof a.url==="string"&&a.url.length>0 || typeof a.src==="string"&&a.src.length>0;
  }
  function scan(){
    var rows=[], P=window.project; if(!P||!P.tracks) return rows;
    var end=window.amiyoContentEnd?window.amiyoContentEnd():0, miss={}, zero=0, hidden=[], aClips=0, aLive=0, iv=[];
    P.tracks.forEach(function(tr){
      var cl=tr.clips||[];
      cl.forEach(function(c){
        if(!(c.duration>0)) zero++;
        if(c.assetId){ var a=(P.assets||{})[c.assetId]; if(!have(a)) miss[c.assetId]=(a&&a.name)||c.assetId; }
      });
      if(tr.hidden&&cl.length) hidden.push((tr.name||tr.kind||"Track")+" ("+cl.length+")");
      if(tr.kind==="audio"&&cl.length){ aClips+=cl.length; if(!tr.muted) aLive+=cl.length; }
      if(tr.kind==="video"&&!tr.hidden) cl.forEach(function(c){ if(c.duration>0) iv.push([c.start,c.start+c.duration]); });
    });
    var mk=Object.keys(miss);
    rows.push(mk.length?{bad:1,t:mk.length+" missing media file"+(mk.length>1?"s":"")+": "+mk.slice(0,3).map(function(k){return miss[k];}).join(", ")+(mk.length>3?"…":"")+". Those clips export as blank. Relink or re-import first."}:{ok:1,t:"All media is available"});
    iv.sort(function(a,b){return a[0]-b[0];});
    var gaps=[], pos=0; iv.forEach(function(r){ if(r[0]-pos>0.2) gaps.push([pos,r[0]]); pos=Math.max(pos,r[1]); });
    if(iv.length&&end-pos>0.2&&end-pos<1e6) gaps.push([pos,end]);
    if(!iv.length&&end>0) rows.push({warn:1,t:"No picture clips on any visible video track. The video will be black."});
    else rows.push(gaps.length?{warn:1,t:gaps.length+" black gap"+(gaps.length>1?"s":"")+" on the picture: "+gaps.slice(0,3).map(function(g){return tc(g[0])+"–"+tc(g[1]);}).join(", ")+(gaps.length>3?"…":"")}:{ok:1,t:"No black gaps"});
    if(window.__amiyoXMute) rows.push(aClips?{warn:1,t:"Sound is switched off in the export settings, so the "+aClips+" audio clip"+(aClips>1?"s":"")+" will be silent."}:{ok:1,t:"Sound off (as chosen)"});
    else if(aClips&&!aLive) rows.push({warn:1,t:"Every audio track is muted. The exported video will have no music or voice from them."});
    else rows.push({ok:1,t:aClips?"Audio tracks are live":"No separate audio tracks"});
    if(hidden.length) rows.push({warn:1,t:"Hidden track"+(hidden.length>1?"s":"")+" still hold clips: "+hidden.slice(0,3).join(", ")+". Show them if they belong in the video."});
    if(zero) rows.push({warn:1,t:zero+" clip"+(zero>1?"s have":" has")+" no length and will not appear."});
    return rows;
  }
  function paint(){
    var box=$("x12Check"); if(!box) return;
    var rows; try{ rows=(window.amiyoExportCheck||scan)(); }catch(e){ window.__swl&&window.__swl(e); rows=[]; }
    var bad=rows.filter(function(r){return r.bad;}).length, warn=rows.filter(function(r){return r.warn;}).length;
    var head=bad?"Fix before exporting":(warn?warn+" thing"+(warn>1?"s":"")+" to look at":"Ready to export");
    box.querySelector("h4").textContent="Check · "+head;
    box.querySelector("div").innerHTML=rows.map(function(r){
      var c=r.bad?"#ff91a0":r.warn?"#ffcf70":"#9be0b4", g=r.bad?"✗":r.warn?"⚠":"✓";
      return '<div style="display:flex;gap:6px;color:'+(r.ok?"var(--muted)":c)+'"><span aria-hidden="true">'+g+'</span><span>'+esc(r.t)+'</span></div>';
    }).join("");
  }
  function inject(){
    var body=$("modalBody"); if(!body||$("x12Check")) return;
    var anchor=$("x80Source")||$("expSummary"); if(!anchor||!anchor.parentNode) return;
    var box=document.createElement("div"); box.id="x12Check"; box.className="x80-card"; box.setAttribute("role","status"); box.setAttribute("aria-live","polite");
    box.innerHTML='<h4>Check</h4><div style="font-size:12px;line-height:1.5;display:flex;flex-direction:column;gap:3px"></div>';
    anchor.parentNode.insertBefore(box,anchor.nextSibling);
    paint();
    var t=0; function later(){ clearTimeout(t); t=setTimeout(paint,150); }
    body.addEventListener("click",later); body.addEventListener("input",later); body.addEventListener("change",later);
  }
  var prev=window.openModal;
  window.openModal=function(title){
    var r=prev.apply(this,arguments);
    if(title==="Export video"){ try{ inject(); }catch(e){ try{ window.amiyoReportError&&window.amiyoReportError("The export check could not load",e,{quiet:true}); }catch(x){ window.__swl&&window.__swl(x); } } }
    return r;
  };
  window.amiyoExportCheck=scan;
})();

