      $("x13Q").hidden=o.f==="png"; [].slice.call($("x13Q").children).forEach(function(c){ var on=Number(c.dataset.q)===o.q; c.style.outline=on?"2px solid var(--accent)":"none"; c.setAttribute("aria-pressed",on?"true":"false"); });
