  function tag4(s){ return new Uint8Array([s.charCodeAt(0),s.charCodeAt(1),s.charCodeAt(2),s.charCodeAt(3)]); }
  function box(type,payload){ return cat([u32(8+payload.length),type.length===4&&type.charCodeAt(0)===169?new Uint8Array([169,type.charCodeAt(1),type.charCodeAt(2),type.charCodeAt(3)]):tag4(type),payload]); }
