    var inside=buf.subarray(moov+8,moov+msz), txt=String.fromCharCode.apply(null,inside.subarray(0,Math.min(inside.length,60000)));
    var hasFrag=false; for(var i=0;i<buf.length-8&&!hasFrag;){ var s2=d.getUint32(i); if(s2<8||i+s2>buf.length) break; if(buf[i+4]===109&&buf[i+5]===111&&buf[i+6]===111&&buf[i+7]===102) hasFrag=true; i+=s2; }
