    if(M.title) items.push(ilstItem("\u00a9nam",M.title));
    if(M.author) items.push(ilstItem("\u00a9ART",M.author));
    if(M.comment) items.push(ilstItem("\u00a9cmt",M.comment));
    items.push(ilstItem("\u00a9day",M.date)); items.push(ilstItem("\u00a9too","Amiyo Editor"));
    var hdlr=box("hdlr",cat([u32(0),u32(0),tag4("mdir"),tag4("appl"),u32(0),u32(0),new Uint8Array([0])]));
    var udta=box("udta",box("meta",cat([u32(0),hdlr,box("ilst",cat(items))])));
    var end=moov+msz;
    return cat([buf.subarray(0,moov),u32(msz+udta.length),buf.subarray(moov+4,end),udta,buf.subarray(end)]);
