      var settled=false, cancelPoll=null;
      function finish(v){ if(settled) return; settled=true; clearInterval(cancelPoll); resolve(v); }
      var sel=function(){ return rows.filter(function(r){ return r.on; }); };
      function rowHtml(r,i){
        var d=r.q, info=[]; if(d){ if(d.w) info.push(d.w+"×"+d.h); if(d.d) info.push(tc(d.d)); }
        var flag=r.c?r.c:(d&&d.bad?{lvl:1,t:"This browser could not read it. It may not play."}:(d&&d.slow?{lvl:1,t:"Slow to read. It may be a very large file."}:null));
        var col=flag?(flag.lvl>=2?"#ff91a0":"#ffcf70"):"var(--muted)";
        return '<label style="display:flex;gap:8px;align-items:flex-start;padding:6px 0;border-top:1px solid var(--line,rgba(255,255,255,.1))">'+
          '<input type="checkbox" data-i="'+i+'" '+(r.on?"checked":"")+(r.c&&r.c.lvl>=2?" disabled":"")+' style="margin-top:3px" aria-label="Import '+esc(r.f.name)+'">'+
          '<span aria-hidden="true">'+(ICON[r.k]||"❓")+'</span><span style="min-width:0;flex:1"><span style="display:block;word-break:break-all">'+esc(r.f.name)+'</span>'+
          '<span style="display:block;font-size:11px;color:var(--muted)">'+r.k+' · '+mb(r.f.size)+(info.length?" · "+info.join(" · "):(r.k==="video"||r.k==="image"||r.k==="audio")&&!d?" · checking…":"")+'</span>'+
          (flag?'<span style="display:block;font-size:11px;color:'+col+'">'+(flag.lvl>=2?"✗ ":"⚠ ")+esc(flag.t)+'</span>':"")+'</span></label>';
      }
      function paint(){
        var box=$("x1Rows"); if(box) box.innerHTML=rows.map(rowHtml).join("");
        var n=sel().length, go=$("x1Go"); if(go){ go.textContent=n?("Import "+n+" file"+(n>1?"s":"")):"Nothing selected"; go.disabled=!n; go.style.opacity=n?1:.5; }
        var bad=rows.filter(function(r){ return r.c&&r.c.lvl>=1||(r.q&&(r.q.bad||r.q.slow)); }).length;
        var h=$("x1Head"); if(h) h.textContent=list.length+" file"+(list.length>1?"s":"")+(bad?" · "+bad+" need"+(bad>1?"":"s")+" a look":" · all look fine");
      }
      window.openModal("Import review",
        '<div id="x1Head" style="font-size:12.5px;margin-bottom:6px"></div>'+
        '<div id="x1Rows" style="font-size:12.5px;line-height:1.45;max-height:46vh;overflow:auto"></div>'+
        '<div class="mini-row" style="margin-top:10px"><button type="button" class="chip" id="x1All">Select all</button><button type="button" class="chip" id="x1None">Select none</button></div>'+
        '<label class="field" for="x1Mode" style="margin-top:10px">Show this window</label><select id="x1Mode"><option value="auto">Only when needed (6+ files or a problem)</option><option value="always">Always</option><option value="never">Never</option></select>'+
        '<div class="mini-row" style="margin-top:12px"><button type="button" class="chip" id="x1Go" style="background:var(--accent);color:#1a0c03;font-weight:700"></button><button type="button" class="chip" id="x1No">Cancel</button></div>');
      $("x1Mode").value=mode(); $("x1Mode").onchange=function(){ setMode(this.value); };
      $("x1Rows").addEventListener("change",function(e){ var i=e.target&&e.target.dataset&&e.target.dataset.i; if(i==null) return; rows[+i].on=e.target.checked; paint(); });
      $("x1All").onclick=function(){ rows.forEach(function(r){ if(!(r.c&&r.c.lvl>=2)) r.on=true; }); paint(); };
      $("x1None").onclick=function(){ rows.forEach(function(r){ r.on=false; }); paint(); };
      $("x1Go").onclick=function(){ var pick=sel().map(function(r){ return r.f; }); try{ window.closeModal(); }catch(e){ window.__swl&&window.__swl(e); } finish(pick); };
      $("x1No").onclick=function(){ try{ window.closeModal(); }catch(e){ window.__swl&&window.__swl(e); } finish(null); };
      paint();
      /* closing the window another way counts as Cancel */
      cancelPoll=setInterval(function(){ if(!$("x1Go")) finish(null); },400);
      /* check pictures size and length one file at a time, without slowing the window */
