/* ==================== Script 758 id="amiyo-imp01-progress" ==================== */
/* Import step 1 (Premiere-style): progress panel for imports - file count, bytes, time left, current file, Cancel.
   The import loop itself (importFiles) calls these hooks, so the existing review window, duplicate check and relink keep working unchanged. */
(function(){
  if(window.__amiyoImp01) return; window.__amiyoImp01=true;
  var st=document.createElement("style");
  st.textContent="#impProg{position:fixed;left:10px;right:10px;bottom:76px;max-width:430px;z-index:99990;background:var(--panel,#2b201a);color:var(--text,#e8ecf4);border:1px solid var(--line,#58443a);border-radius:12px;padding:10px 12px;font:12.5px/1.35 system-ui,sans-serif;box-shadow:0 8px 28px rgba(0,0,0,.45)}"+
  "#impProg b{font-size:13px}#impProg .ip-row{display:flex;gap:8px;align-items:center;justify-content:space-between}"+
  "#impProg .ip-bar{height:7px;border-radius:5px;background:rgba(255,255,255,.12);margin:7px 0 5px;overflow:hidden}"+
  "#impProg .ip-fill{height:100%;width:0;background:linear-gradient(90deg,#ff864a,#ff9d6c);transition:width .15s}"+
  "#impProg .ip-name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;opacity:.8}"+
  "#impProg .ip-sub{opacity:.65;font-size:11.5px}#impProg button{min-height:34px;padding:4px 12px;border-radius:8px;border:1px solid var(--line,#58443a);background:transparent;color:inherit;cursor:pointer}";
  document.head.appendChild(st);
  function fmtB(n){ return n>=1e9?(n/1e9).toFixed(2)+" GB":n>=1e6?(n/1e6).toFixed(1)+" MB":Math.max(1,Math.round(n/1e3))+" KB"; }
  function fmtT(s){ s=Math.max(0,Math.round(s)); return s>=60?Math.floor(s/60)+"m "+(s%60)+"s":s+"s"; }
  var S=null;
  window.__amiyoImpCancelled=function(){ return !!(S&&S.cancel); };
  window.__amiyoImpBegin=function(list){
    var total=0; list.forEach(function(f){ total+=(f&&f.size)||0; });
    if(list.length<2&&total<20e6){ S=null; return; }
    S={list:list,total:total,done:0,t0:performance.now(),cancel:false};
    var box=document.createElement("div"); box.id="impProg"; box.setAttribute("role","status"); box.setAttribute("aria-live","polite");
    box.innerHTML='<div class="ip-row"><b id="ipTitle">Importing…</b><button type="button" id="ipCancel">Cancel</button></div><div class="ip-bar"><div class="ip-fill" id="ipFill"></div></div><div class="ip-name" id="ipName"></div><div class="ip-sub" id="ipSub"></div>';
    document.body.appendChild(box); S.box=box;
    box.querySelector("#ipCancel").onclick=function(){ S.cancel=true; this.disabled=true; this.textContent="Stopping…"; };
  };
  window.__amiyoImpFile=function(i,f){
    if(!S) return;
    if(i>0) S.done+=(S.list[i-1]&&S.list[i-1].size)||0;
    var b=S.box, el=(performance.now()-S.t0)/1000, rate=S.done/Math.max(el,.05), left=S.total-S.done;
    b.querySelector("#ipTitle").textContent="Importing "+(i+1)+" of "+S.list.length;
    b.querySelector("#ipName").textContent=(f&&f.name)||"file";
    b.querySelector("#ipFill").style.width=Math.min(100,Math.round(100*(i/S.list.length*.5+S.done/Math.max(S.total,1)*.5)))+"%";
    b.querySelector("#ipSub").textContent=fmtB(S.done)+" of "+fmtB(S.total)+(i>0&&rate>1?" · about "+fmtT(left/rate)+" left":"");
  };
  window.__amiyoImpEnd=function(r){
    if(!S) return; var b=S.box; S=null;
    try{ b.querySelector("#ipFill").style.width="100%"; }catch(e){}
    setTimeout(function(){ try{ b.remove(); }catch(e){} },350);
  };
})();

