/* ==================== Script 759 id="amiyo-imp02-settings" ==================== */
/* Import step 2: one "Import settings" window that remembers your choices on this device.
   Later import steps add their own options to it through amiyoImpSettings.register(). */
(function(){
  if(window.amiyoImpSettings) return;
  var KEY="amiyo_imp_settings";
  function load(){ try{ return JSON.parse(localStorage.getItem(KEY)||"{}")||{}; }catch(e){ return {}; } }
  function save(o){ try{ localStorage.setItem(KEY,JSON.stringify(o)); }catch(e){ window.__swl&&window.__swl(e); } }
  var defs=[];
  var API={
    register:function(d){ if(!d||!d.id) return; defs=defs.filter(function(x){return x.id!==d.id}); defs.push(d); },
    get:function(id){
      var d=defs.filter(function(x){return x.id===id})[0]; if(!d) return undefined;
      if(d.read) { try{ return d.read(); }catch(e){} }
      var o=load(); return o[id]===undefined?d.def:o[id];
    },
    set:function(id,v){
      var d=defs.filter(function(x){return x.id===id})[0];
      if(d&&d.write){ try{ d.write(v); }catch(e){} return; }
      var o=load(); o[id]=v; save(o);
    },
    reset:function(){ save({}); defs.forEach(function(d){ if(d.write) try{ d.write(d.def); }catch(e){} }); },
    open:function(){
      var h='<p style="margin:0 0 10px;opacity:.75;font-size:12.5px">These choices are remembered on this device and used by every import.</p>';
      defs.forEach(function(d){
        var v=API.get(d.id);
        if(d.type==="check") h+='<label style="display:flex;gap:8px;align-items:flex-start;font-size:12.5px;margin:8px 0"><input type="checkbox" data-s="'+d.id+'" '+(v?"checked":"")+'><span>'+d.label+(d.hint?'<br><small style="opacity:.65">'+d.hint+'</small>':'')+'</span></label>';
        else if(d.type==="select") h+='<label class="field" for="imps_'+d.id+'" style="margin-top:10px">'+d.label+'</label><select id="imps_'+d.id+'" data-s="'+d.id+'">'+d.options.map(function(o){return '<option value="'+o[0]+'"'+(String(o[0])===String(v)?" selected":"")+'>'+o[1]+'</option>'}).join("")+'</select>';
        else if(d.type==="number") h+='<label class="field" for="imps_'+d.id+'" style="margin-top:10px">'+d.label+'</label><input type="number" id="imps_'+d.id+'" data-s="'+d.id+'" value="'+v+'" min="'+(d.min||0)+'" max="'+(d.max||999)+'" step="'+(d.step||1)+'">';
      });
      h+='<div class="mini-row" style="margin-top:14px"><button class="chip" id="impsReset">Reset to defaults</button></div>';
      openModal("Import settings",h);
      document.querySelectorAll("#modalBody [data-s]").forEach(function(el){
        el.onchange=function(){ var d=defs.filter(function(x){return x.id===el.dataset.s})[0];
          API.set(el.dataset.s, el.type==="checkbox"?el.checked:(d&&d.type==="number"?Number(el.value):el.value)); };
      });
      var r=document.getElementById("impsReset"); if(r) r.onclick=function(){ API.reset(); API.open(); if(window.toast) window.toast("Import settings reset"); };
    }
  };
  window.amiyoImpSettings=API;
  /* settings that already existed elsewhere keep their own storage, so nothing changes for you */
  API.register({id:"addToTimeline",type:"check",label:"Put imported videos, pictures and audio on the timeline",hint:"Used by the Import window. “Import files” always only adds to Media.",def:true,
    read:function(){ try{ return localStorage.getItem("amiyo_hub_add")!=="0"; }catch(e){ return true; } },
    write:function(v){ try{ localStorage.setItem("amiyo_hub_add",v?"1":"0"); }catch(e){} }});
  API.register({id:"reviewMode",type:"select",label:"Show the Import review window",def:"auto",options:[["auto","Only when needed (6+ files or a problem)"],["always","Always"],["never","Never"]],
    read:function(){ try{ var m=localStorage.getItem("amiyo_import_review"); return /^(auto|always|never)$/.test(m)?m:"auto"; }catch(e){ return "auto"; } },
    write:function(v){ try{ localStorage.setItem("amiyo_import_review",v); }catch(e){} }});
  var oc=window.commandList;
  if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Import settings","amiyoImpSettings.open()"]]); };
  var hb=document.getElementById("hubBtn");
})();

