/* ==================== Script 760 id="amiyo-imp04-folder" ==================== */
/* Import step 4: import a whole folder like Premiere. Import window > "Folder" picks a folder; everything playable inside is imported
   and filed in a Project bin named after its folder (sub-folders become "Folder / Sub"). Hidden and non-media files are skipped quietly.
   Folder imports are never put on the timeline automatically. */
(function(){
  if(window.__amiyoImp04) return; window.__amiyoImp04=true;
  var MEDIA=/\.(mp4|m4v|mov|mkv|webm|avi|3gp|ogv|ts|mts|mp3|wav|m4a|aac|ogg|oga|flac|opus|aif|aiff|jpe?g|png|gif|webp|bmp|avif|svg|heic|heif|tiff?)$/i;
  function relOf(f){ return String((f&&(f.webkitRelativePath||f.__amiyoRel))||""); }
  function isMedia(f){ return !!f&&!!f.name&&f.name.charAt(0)!=="."&&(/^(video|audio|image)\//.test(f.type||"")||MEDIA.test(f.name)); }
  function folderName(f){ var p=relOf(f).split("/"); p.pop(); return p.join(" / ").replace(/\s+/g," ").trim().slice(0,60)||"Imported"; }
  function binFor(name){
    if(!project.bins) project.bins=[];
    var b=project.bins.filter(function(x){return x.name===name})[0];
    if(!b){ b={id:uid("bin"),name:name}; project.bins.push(b); }
    return b.id;
  }
  var inner=window.importFiles;
  window.importFiles=async function(files){
    var list=[].slice.call(files||[]);
    if(!list.some(relOf)) return inner.apply(this,arguments);
    window.__amiyoImportMode={};  /* an (empty) import mode tells the editor not to place these on the timeline */
    var keep=list.filter(isMedia), skipped=list.length-keep.length;
    if(!keep.length){ if(window.toast) window.toast("No videos, sounds or pictures found in that folder"); return []; }
    keep.sort(function(a,b){ return relOf(a).localeCompare(relOf(b),undefined,{numeric:true}); });
    var where={}; keep.forEach(function(f){ if(!relOf(f)) return; var k=f.name+"|"+f.size; (where[k]=where[k]||[]).push(folderName(f)); });
    var before=new Set(Object.keys(project.assets));
    var r=await inner.call(this,keep), n=0, bins={};
    try{
      Object.keys(project.assets).forEach(function(id){
        if(before.has(id)) return; var a=project.assets[id]; if(!a) return;
        var q=where[a.name+"|"+a.size]; if(!q||!q.length) return;
        var fn=q.shift(); a.binId=binFor(fn); bins[fn]=1; n++;
      });
      if(n){ scheduleAutosave(); renderLeftPanel(); }
    }catch(e){ window.__swl&&window.__swl(e); }
    var nb=Object.keys(bins).length;
    if(window.toast&&n) window.toast(n+" file"+(n===1?"":"s")+" imported into "+nb+" bin"+(nb===1?"":"s")+(skipped?" ("+skipped+" other files skipped)":""),4500);
    return r;
  };
})();

;
/* ==================== Script 761 id="amiyo-imp03-autobin" ==================== */
/* Import step 3: new media is filed into bins like Premiere's Project panel.
   If a bin is open, imports go into it. Otherwise (setting "Sort into bins by type") videos, audio and pictures go to Videos / Audio / Images. */
(function(){
  if(window.__amiyoImp03) return; window.__amiyoImp03=true;
  var S=window.amiyoImpSettings;
  if(S) S.register({id:"autoBin",type:"select",label:"Sort new media into bins",def:"type",options:[["type","By type: Videos / Audio / Images"],["off","Don't sort (keep in All Media)"]]});
  var NAMES={video:"Videos",audio:"Audio",image:"Images"};
  function binFor(name){
    if(!project.bins) project.bins=[];
    var b=project.bins.filter(function(x){return x.name===name})[0];
    if(!b){ b={id:uid("bin"),name:name}; project.bins.push(b); }
    return b.id;
  }
  var inner=window.importFiles;
  window.importFiles=async function(){
    var before=new Set(Object.keys(project.assets));
    var r=await inner.apply(this,arguments);
    try{
      var mode=S?S.get("autoBin"):"type", ab=document.querySelector("#leftPanel [data-bin].tool-active"), open=ab&&ab.dataset.bin?ab.dataset.bin:null, n=0;
      if(open&&!(project.bins||[]).some(function(b){return b.id===open})) open=null;
      Object.keys(project.assets).forEach(function(id){
        if(before.has(id)) return; var a=project.assets[id]; if(!a||a.binId) return;
        if(open) a.binId=open; else if(mode==="type"&&NAMES[a.type]) a.binId=binFor(NAMES[a.type]); else return;
        n++;
      });
      if(n){ scheduleAutosave(); renderLeftPanel(); }
    }catch(e){ window.__swl&&window.__swl(e); }
    return r;
  };
})();

