      sel.innerHTML=OPTS.map(function(o){return '<option value="'+o[0]+'">'+o[1]+'</option>';}).join("");
      sel.onchange=function(){ mode=sel.value; run(); };
      var cnt=document.createElement("span"); cnt.id="impShowCnt"; cnt.style.cssText="font-size:11.5px;opacity:.7;margin-left:6px";
      anchor.after(sel); sel.after(cnt);
