/* ==================== Script 767 id="amiyo-imp10-link" ==================== */
/* Import step 10: "Import from link" like Premiere's Media Browser. Media panel > 🔗 From link: paste a web address of a video, sound or picture,
   see download progress with Cancel, and it is imported (and filed in bins) like any other file. Sites that block other pages from downloading
   (most do) show a plain-words message. Also in the command palette: "Import from link". */
(function(){
  if(window.__amiyoImp10) return; window.__amiyoImp10=true;
  var EXT={mp4:"video/mp4",m4v:"video/mp4",mov:"video/quicktime",webm:"video/webm",mkv:"video/x-matroska",ogv:"video/ogg",mp3:"audio/mpeg",wav:"audio/wav",m4a:"audio/mp4",aac:"audio/aac",ogg:"audio/ogg",flac:"audio/flac",opus:"audio/ogg",jpg:"image/jpeg",jpeg:"image/jpeg",png:"image/png",gif:"image/gif",webp:"image/webp",avif:"image/avif",bmp:"image/bmp",svg:"image/svg+xml"};
  var ctl=null;
  function $(i){ return document.getElementById(i); }
  function mb(b){ return b>=1073741824?(b/1073741824).toFixed(2)+" GB":b>=1048576?(b/1048576).toFixed(1)+" MB":Math.max(1,Math.round(b/1024))+" KB"; }
  function say(t){ var s=$("lnkMsg"); if(s) s.textContent=t; }
  function nameOf(u,res){
    var n=""; try{ var cd=res.headers.get("content-disposition")||"", m=/filename\*?=(?:UTF-8'')?"?([^";]+)/i.exec(cd); if(m) n=decodeURIComponent(m[1]); }catch(e){}
    if(!n){ try{ n=decodeURIComponent(new URL(u).pathname.split("/").pop()||""); }catch(e){ n=""; } }
    return (n||"linked-media").replace(/[\\/:*?"<>|]/g,"_").slice(0,120);
  }
  async function run(){
    var raw=($("lnkUrl")||{}).value||"", u=raw.trim();
    if(!/^https?:\/\//i.test(u)){ say("Paste a full web address that starts with http:// or https://"); return; }
    var go=$("lnkGo"); if(go) go.disabled=true;
    ctl=new AbortController(); say("Connecting…");
    try{
      var res=await fetch(u,{signal:ctl.signal});
      if(!res.ok) throw new Error("The site answered "+res.status+(res.status===403||res.status===401?" (it needs a login or blocks downloads).":"."));
      var total=+res.headers.get("content-length")||0, ct=(res.headers.get("content-type")||"").split(";")[0].trim().toLowerCase();
      if(total>1.5*1073741824) throw new Error("That file is "+mb(total)+". It is too big for the browser to hold; download it and import from your device.");
      var name=nameOf(u,res), ext=(name.split(".").pop()||"").toLowerCase(), type=EXT[ext]||ct;
      if(!/^(video|audio|image)\//.test(type)) throw new Error("That link is not a video, sound or picture (it is "+(ct||"unknown")+").");
      if(!/\.[a-z0-9]{2,5}$/i.test(name)){ var e2=Object.keys(EXT).filter(function(k){return EXT[k]===type})[0]; if(e2) name+="."+e2; }
      var rd=res.body&&res.body.getReader, parts=[], got=0, t0=Date.now();
      if(rd){ var r=res.body.getReader(); for(;;){ var x=await r.read(); if(x.done) break; parts.push(x.value); got+=x.value.length;
        var sp=got/Math.max(.5,(Date.now()-t0)/1000); say("Downloading "+mb(got)+(total?" of "+mb(total)+" · "+Math.round(got/total*100)+"%":"")+" · "+mb(sp)+"/s"); } }
      else parts=[await res.arrayBuffer()];
      var file=new File(parts,name,{type:type,lastModified:Date.now()});
      if(!file.size) throw new Error("The link gave an empty file.");
      ctl=null; window.closeModal(); window.toast&&window.toast("Downloaded "+name+" ("+mb(file.size)+"). Importing…",3000);
      await window.importFiles([file]);
    }catch(e){
      ctl=null; if(go) go.disabled=false;
      if(e&&e.name==="AbortError"){ say("Cancelled."); return; }
      var msg=(e&&e.message)||String(e);
      if(/Failed to fetch|NetworkError|Load failed/i.test(msg)) msg="Could not download it. The site may block other pages from downloading (CORS), or you are offline. Download the file yourself, then use Import.";
      say(msg); window.__swl&&window.__swl(e);
    }
  }
  window.amiyoImpLink=function(){
    window.openModal("Import from link",
      '<label class="field" for="lnkUrl">Web address of a video, sound or picture</label>'+
      '<input id="lnkUrl" type="url" inputmode="url" autocomplete="off" placeholder="https://example.com/clip.mp4" style="width:100%">'+
      '<div id="lnkMsg" role="status" aria-live="polite" style="font-size:12px;margin-top:8px;min-height:18px;opacity:.85">Only links that allow downloading will work.</div>'+
      '<div class="mini-row" style="margin-top:10px"><button type="button" class="chip" id="lnkGo" style="background:var(--accent);color:#1a0c03;font-weight:700">Download and import</button><button type="button" class="chip" id="lnkNo">Cancel</button></div>');
    var i=$("lnkUrl"); if(i){ i.focus(); i.addEventListener("keydown",function(e){ if(e.key==="Enter") run(); }); }
    $("lnkGo").onclick=run; $("lnkNo").onclick=function(){ if(ctl) ctl.abort(); try{ window.closeModal(); }catch(e){} };
    try{ navigator.clipboard&&navigator.clipboard.readText&&navigator.clipboard.readText().then(function(t){ if(i&&!i.value&&/^https?:\/\/\S+$/i.test((t||"").trim())) i.value=t.trim(); }).catch(function(){}); }catch(e){}
  };
  function ensure(){
    var bar=document.querySelector("#leftPanel .md-bar"); if(!bar||$("impLinkBtn")) return;
    var row=document.createElement("div"); row.className="md-row";
    var b=document.createElement("button"); b.type="button"; b.id="impLinkBtn"; b.className="chip"; b.textContent="🔗 From link"; b.title="Import a video, sound or picture from a web address";
    b.onclick=window.amiyoImpLink; row.appendChild(b); bar.appendChild(row);
  }
  var lp=document.getElementById("leftPanel"), busy=false;
  if(lp) new MutationObserver(function(){ if(busy) return; busy=true; setTimeout(function(){ try{ ensure(); }catch(e){ window.__swl&&window.__swl(e); } busy=false; },80); }).observe(lp,{childList:true,subtree:true});
  var oc=window.commandList;
  if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Import from link","amiyoImpLink()"]]); };
})();

