/* ==================== Script 768 id="amiyo-imp11-relinkall" ==================== */
/* Import step 11: "Relink all" like Premiere's Locate Media. When media is offline (after a reload), the Media panel shows "⚠ N offline - Relink all".
   Pick the folder that holds your files; every offline item with a matching file name (same size preferred) is reconnected in one go,
   and you get a list of what is still missing. Other files in that folder are ignored, nothing new is added. Command palette: "Relink all offline media". */
(function(){
  if(window.__amiyoImp11) return; window.__amiyoImp11=true;
  function offline(){ var o=[]; try{ Object.keys(project.assets||{}).forEach(function(k){ var a=project.assets[k]; if(a&&window.amiyoAssetMissing(a.id||k)) o.push(a); }); }catch(e){ window.__swl&&window.__swl(e); } return o; }
  function esc(s){ return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];}); }
  var pick=document.createElement("input"); pick.type="file"; pick.multiple=true; pick.setAttribute("webkitdirectory",""); pick.style.display="none"; document.body.appendChild(pick);
  pick.addEventListener("change",async function(){
    var files=[].slice.call(pick.files||[]); pick.value=""; if(!files.length) return;
    var miss=offline(); if(!miss.length){ window.toast&&window.toast("Nothing is offline"); return; }
    var byName={}; files.forEach(function(f){ (byName[f.name.toLowerCase()]=byName[f.name.toLowerCase()]||[]).push(f); });
    var take=[], left=[];
    miss.forEach(function(a){
      var c=byName[String(a.origName||a.name||"").toLowerCase()]; if(!c||!c.length){ left.push(a); return; }
      var i=c.findIndex(function(f){ return !a.size||f.size===a.size; }); if(i<0) i=0;
      var f=c.splice(i,1)[0]; take.push(new File([f],f.name,{type:f.type,lastModified:f.lastModified}));   /* plain copy: no folder path, so it is a relink, not a folder import */
    });
    if(take.length){ window.__amiyoImportSkipReview=true; try{ await window.importFiles(take); }catch(e){ window.__swl&&window.__swl(e); } finally{ window.__amiyoImportSkipReview=false; } }
    var still=offline().length;
    if(!take.length||left.length||still){
      window.openModal("Relink result",'<div style="font-size:13px;line-height:1.5">'+(take.length?"✓ Relinked "+take.length+" file"+(take.length>1?"s":"")+".":"No file in that folder matched an offline name.")+
        (left.length?'<div style="margin-top:8px"><b>Still missing ('+left.length+'):</b><div style="max-height:34vh;overflow:auto;font-size:12px;opacity:.85">'+left.map(function(a){return esc(a.name);}).join("<br>")+'</div><div style="margin-top:6px;font-size:12px;opacity:.7">Try another folder, or import the file again.</div></div>':"")+'</div>');
    } else window.toast&&window.toast("All "+take.length+" offline file"+(take.length>1?"s":"")+" relinked",3500);
    try{ renderLeftPanel(); }catch(e){}
  });
  window.amiyoImpRelinkAll=function(){ if(!offline().length){ window.toast&&window.toast("Nothing is offline. All media is connected."); return; } window.toast&&window.toast("Choose the folder that holds your media",2500); pick.click(); };
  function ensure(){
    var bar=document.querySelector("#leftPanel .md-bar"); if(!bar) return;
    var n=offline().length, b=document.getElementById("impRelinkBtn");
    if(!n){ if(b&&b.parentNode) b.parentNode.remove(); return; }
    if(!b){ var row=document.createElement("div"); row.className="md-row"; b=document.createElement("button"); b.type="button"; b.id="impRelinkBtn"; b.className="chip"; b.style.cssText="border-color:#ffcf70;color:#ffcf70"; b.onclick=window.amiyoImpRelinkAll; row.appendChild(b); bar.insertBefore(row,bar.firstChild); }
    b.textContent="⚠ "+n+" offline · Relink all…"; b.title="Pick the folder that holds your media files";
  }
  var lp=document.getElementById("leftPanel"), busy=false;
  if(lp) new MutationObserver(function(){ if(busy) return; busy=true; setTimeout(function(){ try{ ensure(); }catch(e){ window.__swl&&window.__swl(e); } busy=false; },100); }).observe(lp,{childList:true,subtree:true});
  var oc=window.commandList;
  if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Relink all offline media","amiyoImpRelinkAll()"]]); };
})();

