   ".impSw{display:flex;align-items:center;gap:10px;width:100%;padding:10px;margin:4px 0;border-radius:10px;border:1px solid rgba(255,255,255,.18);background:transparent;color:inherit;font:600 14px system-ui;cursor:pointer;min-height:44px}.impSw i{width:20px;height:20px;border-radius:10px;display:inline-block;border:1px solid rgba(255,255,255,.4)}";
  document.head.appendChild(st);
