    s.innerHTML='<option value="any">Label: Any</option><option value="none">Label: None</option>'+COL.map(function(c){return '<option value="'+c[0]+'">Label: '+c[1]+'</option>';}).join("");
    s.value=mode; s.onchange=function(){ mode=s.value; run(); }; var after=document.getElementById("impShowCnt")||anchor; after.after(s);
