/* ==================== Script 771 id="amiyo-imp14-history" ==================== */
/* Import step 14: Import history with "Undo import". Every import that adds media is logged in the project (time, how many files, which ones).
   Media panel > 🕘 History shows the latest imports; "Remove from project" takes that import's media out again (items used on the timeline are kept).
   Removing is one step in the editor's own Undo. Command palette: "Import history". */
(function(){
  if(window.__amiyoImp14) return; window.__amiyoImp14=true;
  function esc(s){ return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];}); }
  function used(){ var u={}; (project.tracks||[]).forEach(function(t){ (t.clips||[]).forEach(function(c){ if(c.assetId) u[c.assetId]=1; }); }); return u; }
  var inner=window.importFiles;
  window.importFiles=async function(files){
    var asked=0; try{ asked=[].slice.call(files||[]).length; }catch(e){}
    var before=new Set(Object.keys(project.assets||{})), r=await inner.apply(this,arguments);
    try{
      var ids=Object.keys(project.assets).filter(function(k){ return !before.has(k); });
      if(ids.length){ var log=project.importLog=project.importLog||[]; log.unshift({t:Date.now(),ask:asked,ids:ids,names:ids.map(function(k){return project.assets[k].name;}).slice(0,60)}); if(log.length>30) log.length=30; scheduleAutosave(); }
    }catch(e){ window.__swl&&window.__swl(e); }
    return r;
  };
  function remove(i){
    var e=(project.importLog||[])[i]; if(!e) return;
    var u=used(), live=e.ids.filter(function(k){ return project.assets[k]; }), del=live.filter(function(k){ return !u[k]; }), keep=live.length-del.length;
    if(!del.length){ window.toast&&window.toast(live.length?"Those items are used on the timeline, so they were kept":"They are already gone"); return; }
    Promise.resolve(window.amiyoOk("Remove "+del.length+" item"+(del.length>1?"s":"")+" added by this import?"+(keep?" ("+keep+" used on the timeline will be kept.)":""),{okLabel:"Remove",danger:true})).then(function(ok){
      if(!ok) return;
      var b=deepClone(serializableProject()); del.forEach(function(k){ delete project.assets[k]; });
      e.ids=e.ids.filter(function(k){ return project.assets[k]; });
      try{ recordHistory("Undo import",b,serializableProject()); updateUndoRedo(); }catch(x){ window.__swl&&window.__swl(x); }
      scheduleAutosave(); try{ renderAll(); }catch(x){ try{ renderLeftPanel(); }catch(y){} }
      window.toast&&window.toast(del.length+" item"+(del.length>1?"s":"")+" removed. Ctrl+Z brings them back.",4000);
    });
  }
  window.amiyoImpHistory=function(){
    var log=project.importLog||[];
    var body=!log.length?'<div style="font-size:13px;opacity:.8">No imports yet in this project.</div>':
      '<div style="max-height:52vh;overflow:auto">'+log.map(function(e,i){
        var live=e.ids.filter(function(k){ return project.assets[k]; }).length, d=new Date(e.t);
        return '<div style="padding:8px 0;border-top:1px solid rgba(255,255,255,.1);font-size:12.5px"><b>'+d.toLocaleDateString()+" "+d.toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})+'</b> · '+e.ids.length+' added'+(e.ask&&e.ask>e.ids.length?' of '+e.ask+' picked':'')+(live<e.ids.length?' · '+live+' still here':'')+
          '<div style="opacity:.7;word-break:break-all;margin:3px 0">'+esc(e.names.slice(0,3).join(", "))+(e.names.length>3?" +"+(e.names.length-3)+" more":"")+'</div>'+
          (live?'<button type="button" class="chip" data-rm="'+i+'">Remove from project</button>':'')+'</div>'; }).join("")+'</div>';
    window.openModal("Import history",body);
    document.querySelectorAll("[data-rm]").forEach(function(b){ b.onclick=function(){ try{ window.closeModal(); }catch(x){} remove(+b.dataset.rm); }; });
  };
  function ensure(){
    var bar=document.querySelector("#leftPanel .md-bar"); if(!bar||document.getElementById("impHistBtn")) return;
    var host=document.getElementById("impLinkBtn"), b=document.createElement("button"); b.type="button"; b.id="impHistBtn"; b.className="chip"; b.textContent="🕘 History"; b.title="Recent imports"; b.onclick=window.amiyoImpHistory;
    if(host&&host.parentNode) host.parentNode.appendChild(b); else { var row=document.createElement("div"); row.className="md-row"; row.appendChild(b); bar.appendChild(row); }
  }
  var lp=document.getElementById("leftPanel"), busy=false;
  if(lp) new MutationObserver(function(){ if(busy) return; busy=true; setTimeout(function(){ try{ ensure(); }catch(e){ window.__swl&&window.__swl(e); } busy=false; },130); }).observe(lp,{childList:true,subtree:true});
  var oc=window.commandList;
  if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Import history","amiyoImpHistory()"]]); };
})();

