/* ==================== Script 772 id="amiyo-imp15-cardwave" ==================== */
/* Import step 15: waveforms on audio cards, like Premiere's audio thumbnails. Sound files show their real waveform in the Media panel instead of the word "AUDIO".
   Built one file at a time, only for cards on screen, using the editor's own waveform cache (so the timeline reuses the same work). Skipped in Lite mode
   and for very large files. Import settings: "Waveforms on audio cards". */
(function(){
  if(window.__amiyoImp15) return; window.__amiyoImp15=true;
  var S=window.amiyoImpSettings;
  if(S) S.register({id:"cardWave",type:"select",label:"Waveforms on audio cards",def:"on",options:[["on","On (built when the card is on screen)"],["off","Off"]]});
  var st=document.createElement("style");
  st.textContent=".asset .imp-wave{position:absolute;inset:0;width:100%;height:100%;object-fit:fill;opacity:.95;pointer-events:none}";
  document.head.appendChild(st);
  var queue=[], queued=new Set(), running=false, io=null;
  function on(){ try{ return !S||S.get("cardWave")!=="off"; }catch(e){ return true; } }
  function paint(id){
    var c=null; try{ c=waveformCache.get(id); }catch(e){} if(!c||!c.dataUrl) return;
    document.querySelectorAll('#leftPanel .asset[data-asset="'+id+'"]').forEach(function(el){
      var th=el.querySelector(".thumb"); if(!th) return; var im=th.querySelector(".imp-wave");
      if(!im){ if(getComputedStyle(th).position==="static") th.style.position="relative"; im=document.createElement("img"); im.className="imp-wave"; im.alt="Waveform"; th.appendChild(im); var lbl=th.querySelector("span"); if(lbl&&/^AUDIO$/i.test(lbl.textContent)) lbl.style.opacity=".35"; }
      if(im.getAttribute("src")!==c.dataUrl) im.src=c.dataUrl;
    });
  }
  async function pump(){
    if(running) return; running=true;
    try{ while(queue.length){ var id=queue.shift(), a=project.assets[id]; if(!a||!on()) continue;
      try{ if(typeof amiyoAssetMissing==="function"&&amiyoAssetMissing(id)) continue; await buildWaveform(a); paint(id); }catch(e){ window.__swl&&window.__swl(e); }
      await new Promise(function(r){ setTimeout(r,120); }); } }
    finally{ running=false; }
  }
  function want(id){ if(queued.has(id)) return; var a=project.assets[id]; if(!a||a.type!=="audio") return; queued.add(id); queue.push(id); pump(); }
  function scan(){
    if(typeof buildWaveform!=="function"||typeof waveformCache==="undefined") return;
    var cards=document.querySelectorAll('#leftPanel .asset[data-asset]');
    if(!io&&"IntersectionObserver" in window) io=new IntersectionObserver(function(es){ es.forEach(function(e){ if(e.isIntersecting&&e.target.dataset.asset){ var id=e.target.dataset.asset; try{ if(waveformCache.has(id)) paint(id); else if(on()) want(id); }catch(x){} } }); },{rootMargin:"120px"});
    cards.forEach(function(el){
      var a=project.assets[el.dataset.asset]; if(!a||a.type!=="audio") return;
      try{ if(waveformCache.has(a.id)){ paint(a.id); return; } }catch(e){}
      if(io){ if(!el.__impW){ el.__impW=1; io.observe(el); } } else if(on()) want(a.id);
    });
  }
  var lp=document.getElementById("leftPanel"), busy=false;
  if(lp) new MutationObserver(function(){ if(busy) return; busy=true; setTimeout(function(){ try{ scan(); }catch(e){ window.__swl&&window.__swl(e); } busy=false; },150); }).observe(lp,{childList:true,subtree:true});
})();

