/* ==================== Script 773 id="amiyo-imp16-offlinecheck" ==================== */
/* Import step 16: offline check when a project opens, like Premiere's "Locate files" prompt. A few seconds after the editor loads, if any media
   the timeline uses is offline, a banner says how many files and clips are affected, with "Relink all…" and "Later". Shown once per load. Never blocks editing. */
(function(){
  if(window.__amiyoImp16) return; window.__amiyoImp16=true;
  var shown=false, tries=0;
  function esc(s){ return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];}); }
  function scan(){
    var off={}, clips=0;
    (project.tracks||[]).forEach(function(t){ (t.clips||[]).forEach(function(c){ if(c.assetId&&project.assets[c.assetId]&&window.amiyoAssetMissing(c.assetId)){ off[c.assetId]=1; clips++; } }); });
    return {ids:Object.keys(off),clips:clips};
  }
  function banner(r){
    var d=document.createElement("div"); d.id="impOffBar"; d.setAttribute("role","alert");
    d.style.cssText="position:fixed;left:10px;right:10px;top:10px;max-width:460px;margin:0 auto;z-index:99991;background:#2b2210;color:#ffe9b8;border:1px solid #ffcf70;border-radius:12px;padding:10px 12px;font:13px/1.4 system-ui;box-shadow:0 6px 24px rgba(0,0,0,.45)";
    var names=r.ids.slice(0,3).map(function(k){ return esc(project.assets[k].name); }).join(", ")+(r.ids.length>3?" +"+(r.ids.length-3)+" more":"");
    d.innerHTML='<b>⚠ '+r.ids.length+' media file'+(r.ids.length>1?"s are":" is")+' offline</b> ('+r.clips+' clip'+(r.clips>1?"s":"")+' on the timeline)<div style="opacity:.8;font-size:12px;word-break:break-all;margin:3px 0 8px">'+names+'</div>'+
      '<button type="button" class="chip" id="impOffGo" style="background:var(--accent,#ff9f2e);color:#1a0c03;font-weight:700">Relink all…</button> <button type="button" class="chip" id="impOffNo">Later</button>';
    document.body.appendChild(d);
    document.getElementById("impOffGo").onclick=function(){ d.remove(); window.amiyoImpRelinkAll&&window.amiyoImpRelinkAll(); };
    document.getElementById("impOffNo").onclick=function(){ d.remove(); };
    setTimeout(function(){ if(d.parentNode) d.remove(); },20000);
  }
  function check(){
    if(shown) return; tries++;
    try{
      if(typeof project==="undefined"||!project||!project.assets||typeof amiyoAssetMissing!=="function"){ if(tries<10) setTimeout(check,1500); return; }
      if(!Object.keys(project.assets).length){ if(tries<4) setTimeout(check,2000); return; }   /* the project may still be loading */
      var r=scan(); shown=true; if(r.ids.length) banner(r);
    }catch(e){ window.__swl&&window.__swl(e); }
  }
  setTimeout(check,3500);
  window.amiyoImpOfflineCheck=function(){ shown=false; tries=0; var o=document.getElementById("impOffBar"); if(o) o.remove(); var r=scan(); if(r.ids.length) banner(r); else window.toast&&window.toast("No offline media on the timeline"); shown=true; };
  var oc=window.commandList;
  if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Check for offline media","amiyoImpOfflineCheck()"]]); };
})();

