/* ==================== Script 774 id="amiyo-imp17-presets" ==================== */
/* Import step 17: import presets, like Premiere's ingest presets. Save your current Import settings (timeline, review window, bins, view, waveforms)
   under a name and switch with one tap. Two ready-made presets: "Quick edit" (straight to the timeline) and "Organise first" (review + bins, nothing on the timeline).
   Media panel > 📋 Presets, or Import settings. Command palette: "Import presets". */
(function(){
  if(window.__amiyoImp17) return; window.__amiyoImp17=true;
  var S=window.amiyoImpSettings, KEY="amiyo_imp_presets";
  window.amiyoImpPresetKeys=window.amiyoImpPresetKeys||["addToTimeline","reviewMode","autoBin","mediaView","cardWave"];
  var BUILT=[{name:"Quick edit",v:{addToTimeline:true,reviewMode:"never",autoBin:"off"},fixed:1},{name:"Organise first",v:{addToTimeline:false,reviewMode:"always",autoBin:"type"},fixed:1}];
  function load(){ try{ var l=JSON.parse(localStorage.getItem(KEY)||"[]"); return Array.isArray(l)?l:[]; }catch(e){ return []; } }
  function save(l){ try{ localStorage.setItem(KEY,JSON.stringify(l)); }catch(e){ window.__swl&&window.__swl(e); } }
  function esc(s){ return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];}); }
  function current(){ var v={}; window.amiyoImpPresetKeys.forEach(function(k){ var x=S&&S.get(k); if(x!==undefined) v[k]=x; }); return v; }
  function same(a,b){ return Object.keys(a).every(function(k){ return !(k in b)||String(a[k])===String(b[k]); }); }
  function apply(p){ if(!S) return; Object.keys(p.v).forEach(function(k){ if(S.get(k)!==undefined) S.set(k,p.v[k]); }); window.toast&&window.toast("Preset “"+p.name+"” applied",2800); try{ renderLeftPanel(); }catch(e){} }
  function open(){
    if(!S){ window.toast&&window.toast("Import settings are not available"); return; }
    var all=BUILT.concat(load()), cur=current();
    window.openModal("Import presets",
      '<div style="font-size:12px;opacity:.7;margin-bottom:6px">Tap a preset to use it. The tick shows the one that matches your settings now.</div>'+
      all.map(function(p,i){ var on=same(cur,p.v)&&same(p.v,cur);
        return '<div style="display:flex;gap:6px;align-items:center;margin:5px 0"><button type="button" class="chip" data-ap="'+i+'" style="flex:1;text-align:left;min-height:42px">'+(on?"✓ ":"")+esc(p.name)+'</button>'+(p.fixed?'':'<button type="button" class="chip" data-dp="'+(i-BUILT.length)+'" aria-label="Delete preset '+esc(p.name)+'">✕</button>')+'</div>'; }).join("")+
      '<div class="mini-row" style="margin-top:12px"><button type="button" class="chip" id="impPrNew" style="background:var(--accent);color:#1a0c03;font-weight:700">Save current settings as preset…</button></div>');
    document.querySelectorAll("[data-ap]").forEach(function(b){ b.onclick=function(){ var p=all[+b.dataset.ap]; try{ window.closeModal(); }catch(e){} apply(p); }; });
    document.querySelectorAll("[data-dp]").forEach(function(b){ b.onclick=function(){ var l=load(); l.splice(+b.dataset.dp,1); save(l); open(); }; });
    document.getElementById("impPrNew").onclick=async function(){
      try{ window.closeModal(); }catch(e){}
      var n=await Promise.resolve(window.amiyoAsk("Name this preset","",{okLabel:"Save"})); if(n==null) return; n=String(n).trim().slice(0,30); if(!n) return;
      var l=load().filter(function(p){ return p.name.toLowerCase()!==n.toLowerCase(); }); l.push({name:n,v:current()}); save(l); window.toast&&window.toast("Preset “"+n+"” saved",2800); open();
    };
  }
  window.amiyoImpPresets=open;
  function ensure(){
    var bar=document.querySelector("#leftPanel .md-bar"); if(!bar||document.getElementById("impPresetBtn")) return;
    var host=document.getElementById("impLinkBtn"), b=document.createElement("button"); b.type="button"; b.id="impPresetBtn"; b.className="chip"; b.textContent="📋 Presets"; b.title="Import presets"; b.onclick=open;
    if(host&&host.parentNode) host.parentNode.appendChild(b); else { var row=document.createElement("div"); row.className="md-row"; row.appendChild(b); bar.appendChild(row); }
  }
  var lp=document.getElementById("leftPanel"), busy=false;
  if(lp) new MutationObserver(function(){ if(busy) return; busy=true; setTimeout(function(){ try{ ensure(); }catch(e){ window.__swl&&window.__swl(e); } busy=false; },140); }).observe(lp,{childList:true,subtree:true});
  var oc=window.commandList;
  if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Import presets","amiyoImpPresets()"]]); };
})();

