/* ==================== Script 775 id="amiyo-imp18-fixhelper" ==================== */
/* Import step 18: "Can't play this" helper. After an import, files this browser cannot play smoothly (HEVC/H.265, ProRes, AC-3, MKV with odd codecs, unreadable files)
   are listed in one window with the reason and the exact fix, e.g. "convert to MP4 (H.264 + AAC) with HandBrake or ffmpeg". A copyable ffmpeg line is included per file.
   Media panel > 🩺 Playback check (also in the command palette) checks everything in the project. */
(function(){
  if(window.__amiyoImp18) return; window.__amiyoImp18=true;
  function esc(s){ return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];}); }
  function issue(a){
    if(!a||a.type==="image") return null; var m=a.meta||{};
    try{ if(amiyoAssetMissing(a.id)) return null; }catch(e){}
    var vc=m.videoCodec||"", ac=m.audioCodec||"", c=m.container||"";
    if(/HEVC|H\.265/i.test(vc)) return "H.265 (HEVC) video: many browsers cannot play or export it smoothly.";
    if(/ProRes/i.test(vc)) return "ProRes video: browsers cannot decode it.";
    if(/MPEG-4 Part 2/i.test(vc)) return "Old MPEG-4 video: playback is unreliable.";
    if(/AC-3|E-AC-3/i.test(ac)) return "Dolby (AC-3) sound: you may get picture with no sound.";
    if(/ALAC/i.test(ac)) return "Apple Lossless sound: not supported in most browsers.";
    if(/\.(avi|wmv|flv|mts|ts|3gp)$/i.test(a.name||"")) return "This container ("+(a.name.split(".").pop().toUpperCase())+") is poorly supported by browsers.";
    if(a.type==="video"&&!(a.duration>0)&&!(a.width>0)) return "The browser could not read this file. It may be damaged or use an unsupported format.";
    return null;
  }
  function cmd(a){ var base=(a.name||"clip").replace(/\.[^.]+$/,""); return 'ffmpeg -i "'+(a.name||"input")+'" -c:v libx264 -crf 20 -pix_fmt yuv420p -c:a aac -b:a 192k "'+base+'_h264.mp4"'; }
  function show(ids,title){
    var rows=ids.map(function(id){ var a=project.assets[id]; return a?{a:a,why:issue(a)}:null; }).filter(function(r){ return r&&r.why; });
    if(!rows.length){ if(title!=="auto") window.toast&&window.toast("Everything here should play fine in this browser",3500); return; }
    window.openModal(rows.length+" file"+(rows.length>1?"s":"")+" may not play well",
      '<div style="font-size:12.5px;opacity:.8;margin-bottom:6px">Convert each one to <b>MP4 (H.264 video + AAC sound)</b>, then import the new file. Free tools: HandBrake, or ffmpeg with the line shown.</div>'+
      '<div style="max-height:50vh;overflow:auto">'+rows.map(function(r,i){ return '<div style="padding:8px 0;border-top:1px solid rgba(255,255,255,.1);font-size:12.5px"><b style="word-break:break-all">'+esc(r.a.name)+'</b><div style="color:#ffcf70">⚠ '+esc(r.why)+'</div>'+
        (r.a.type==="video"?'<button type="button" class="chip" data-cp="'+i+'" style="margin-top:5px">Copy ffmpeg line</button>':"")+'</div>'; }).join("")+'</div>');
    document.querySelectorAll("[data-cp]").forEach(function(b){ b.onclick=function(){ var t=cmd(rows[+b.dataset.cp].a); try{ navigator.clipboard.writeText(t).then(function(){ window.toast&&window.toast("Copied. Paste it in a terminal next to the file.",3500); },function(){ window.prompt("Copy this line:",t); }); }catch(e){ window.prompt("Copy this line:",t); } }; });
  }
  window.amiyoImpPlayCheck=function(){ show(Object.keys(project.assets),"manual"); };
  var inner=window.importFiles;
  window.importFiles=async function(){
    var before=new Set(Object.keys(project.assets)), r=await inner.apply(this,arguments);
    setTimeout(function(){ try{ var ids=Object.keys(project.assets).filter(function(k){ return !before.has(k); }); if(ids.length) show(ids,"auto"); }catch(e){ window.__swl&&window.__swl(e); } },4500);   /* wait for file info (step 6) to finish reading */
    return r;
  };
  function ensure(){
    var bar=document.querySelector("#leftPanel .md-bar"); if(!bar||document.getElementById("impPlayBtn")) return;
    var host=document.getElementById("impLinkBtn"), b=document.createElement("button"); b.type="button"; b.id="impPlayBtn"; b.className="chip"; b.textContent="🩺 Playback check"; b.title="Find files that may not play in this browser"; b.onclick=window.amiyoImpPlayCheck;
    if(host&&host.parentNode) host.parentNode.appendChild(b); else { var row=document.createElement("div"); row.className="md-row"; row.appendChild(b); bar.appendChild(row); }
  }
  var lp=document.getElementById("leftPanel"), busy=false;
  if(lp) new MutationObserver(function(){ if(busy) return; busy=true; setTimeout(function(){ try{ ensure(); }catch(e){ window.__swl&&window.__swl(e); } busy=false; },150); }).observe(lp,{childList:true,subtree:true});
  var oc=window.commandList;
  if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Playback check (files that may not play)","amiyoImpPlayCheck()"]]); };
})();

