/* ==================== Script 777 id="amiyo-imp20-slideshow" ==================== */
/* Import step 20: pictures to a slideshow, like Premiere's "Automate to Sequence". Media panel > 🎞 Slideshow… places every picture the panel is showing
   one after another on the video track at the playhead. Choose seconds per picture and the order (as shown, name A-Z, newest first). One step in Undo.
   Tip: import a folder of pictures, then use this. Command palette: "Pictures to slideshow". */
(function(){
  if(window.__amiyoImp20) return; window.__amiyoImp20=true;
  function pics(){ var ids=[]; document.querySelectorAll("#leftPanel .asset[data-asset]").forEach(function(el){ var a=project.assets[el.dataset.asset]; if(a&&a.type==="image"&&el.offsetParent!==null) ids.push(a.id); }); return ids; }
  window.amiyoImpSlideshow=function(){
    var ids=pics(); if(!ids.length){ window.toast&&window.toast("No pictures are showing in Media. Check Search and Show filters."); return; }
    window.openModal("Slideshow from "+ids.length+" picture"+(ids.length>1?"s":""),
      '<label class="field" for="ssSec">Seconds per picture</label><input id="ssSec" type="number" min="0.5" max="60" step="0.5" value="4" style="width:100%">'+
      '<label class="field" for="ssOrd">Order</label><select id="ssOrd"><option value="shown">As shown in Media</option><option value="name">Name A–Z (numbers in order)</option><option value="new">Newest file first</option></select>'+
      '<div id="ssTot" style="font-size:12px;opacity:.75;margin-top:8px"></div>'+
      '<div class="mini-row" style="margin-top:12px"><button type="button" class="chip" id="ssGo" style="background:var(--accent);color:#1a0c03;font-weight:700">Place on timeline</button><button type="button" class="chip" id="ssNo">Cancel</button></div>');
    var $=function(i){ return document.getElementById(i); };
    function tot(){ var s=Math.max(.5,+$("ssSec").value||4); $("ssTot").textContent="Total length: "+(Math.round(s*ids.length*10)/10)+" seconds, starting at the playhead."; }
    $("ssSec").oninput=tot; tot();
    $("ssNo").onclick=function(){ try{ window.closeModal(); }catch(e){} };
    $("ssGo").onclick=function(){
      var s=Math.min(60,Math.max(.5,+$("ssSec").value||4)), o=$("ssOrd").value, list=ids.slice();
      if(o==="name") list.sort(function(a,b){ return project.assets[a].name.localeCompare(project.assets[b].name,undefined,{numeric:true,sensitivity:"base"}); });
      else if(o==="new") list.sort(function(a,b){ return ((project.assets[b].meta||{}).modified||0)-((project.assets[a].meta||{}).modified||0); });
      try{ window.closeModal(); }catch(e){}
      try{
        var b=deepClone(serializableProject()), track=getTrack("video"), total=s*list.length, start=nearestGap(track.clips,currentTime,total), last=null;
        list.forEach(function(id,i){
          var c={id:uid("clip"),assetId:id,start:start+i*s,duration:s,inPoint:0,outPoint:s,volume:1,opacity:1,speed:1,rotation:0,scale:1,x:.5,y:.5,trimL:0,trimR:0,fit:"contain",effects:[],keyframes:[],transitionIn:null,transitionOut:null};
          track.clips.push(c); last=c;
        });
        track.clips.sort(function(x,y){ return x.start-y.start; });
        if(last){ selectedClipId=last.id; selectedTrackId=track.id; }
        recordHistory("Slideshow from pictures",b,serializableProject()); scheduleAutosave(); renderAll();
        window.toast&&window.toast(list.length+" pictures placed ("+Math.round(total*10)/10+" s)",3500);
      }catch(e){ window.__swl&&window.__swl(e); window.toast&&window.toast("Could not place the pictures"); }
    };
  };
  function ensure(){
    var bar=document.querySelector("#leftPanel .md-bar"); if(!bar||document.getElementById("impSlideBtn")) return;
    var host=document.getElementById("impLinkBtn"), b=document.createElement("button"); b.type="button"; b.id="impSlideBtn"; b.className="chip"; b.textContent="🎞 Slideshow…"; b.title="Place shown pictures one after another"; b.onclick=window.amiyoImpSlideshow;
    if(host&&host.parentNode) host.parentNode.appendChild(b); else { var row=document.createElement("div"); row.className="md-row"; row.appendChild(b); bar.appendChild(row); }
  }
  var lp=document.getElementById("leftPanel"), busy=false;
  if(lp) new MutationObserver(function(){ if(busy) return; busy=true; setTimeout(function(){ try{ ensure(); }catch(e){ window.__swl&&window.__swl(e); } busy=false; },170); }).observe(lp,{childList:true,subtree:true});
  var oc=window.commandList;
  if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Pictures to slideshow","amiyoImpSlideshow()"]]); };
})();

