/* ==================== Script 778 id="amiyo-imp21-report" ==================== */
/* Import step 21: media report, like exporting a Project panel list. Media panel > 📄 Report downloads a spreadsheet file (.csv, opens in Excel / Sheets)
   with one row per media item: name, type, bin, label, length, size, resolution, frame rate, codecs, container, used on timeline (times), offline, tags, favourite.
   Choose "Everything" or only what the panel shows now. Command palette: "Export media report". */
(function(){
  if(window.__amiyoImp21) return; window.__amiyoImp21=true;
  function q(v){ v=v==null?"":String(v); if(/^[=+\-@]/.test(v)) v="'"+v; return /[",\n\r]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v; }
  function tc(s){ s=+s||0; var h=Math.floor(s/3600), m=Math.floor(s%3600/60), x=(s%60).toFixed(2); return (h?h+":":"")+(h&&m<10?"0":"")+m+":"+(x<10?"0":"")+x; }
  function rows(ids){
    var uses={}; (project.tracks||[]).forEach(function(t){ (t.clips||[]).forEach(function(c){ if(c.assetId) uses[c.assetId]=(uses[c.assetId]||0)+1; }); });
    var bins={}; (project.bins||[]).forEach(function(b){ bins[b.id]=b.name; });
    var H=["Name","Type","Bin","Label","Length","Size (MB)","Width","Height","Frame rate","Video codec","Audio codec","Container","Used on timeline (times)","Offline","Favourite","Tags"], out=[H];
    ids.forEach(function(id){ var a=project.assets[id]; if(!a) return; var m=a.meta||{}, off=false; try{ off=!!amiyoAssetMissing(id); }catch(e){}
      out.push([a.name,a.type,bins[a.binId]||"All Media",a.label||"",a.type==="image"?"":tc(a.duration),a.size?(a.size/1048576).toFixed(2):"",a.width||"",a.height||"",m.fps||"",m.videoCodec||"",m.audioCodec||"",m.container||"",uses[id]||0,off?"yes":"",a.favorite?"yes":"",(a.tags||[]).join(" ")]); });
    return out;
  }
  function shown(){ var ids=[]; document.querySelectorAll("#leftPanel .asset[data-asset]").forEach(function(el){ if(el.offsetParent!==null) ids.push(el.dataset.asset); }); return ids; }
  function download(ids,label){
    var r=rows(ids); if(r.length<2){ window.toast&&window.toast("No media to report"); return; }
    var csv="\ufeff"+r.map(function(x){ return x.map(q).join(","); }).join("\r\n");
    var url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"})), a=document.createElement("a");
    a.href=url; a.download="media-report-"+new Date().toISOString().slice(0,10)+".csv"; document.body.appendChild(a); a.click(); a.remove(); setTimeout(function(){ URL.revokeObjectURL(url); },4000);
    window.toast&&window.toast("Report saved: "+(r.length-1)+" items ("+label+")",3500);
  }
  window.amiyoImpReport=function(){
    var all=Object.keys(project.assets||{}), sh=shown();
    if(!all.length){ window.toast&&window.toast("There is no media in this project yet"); return; }
    if(sh.length===all.length||!sh.length){ download(all,"everything"); return; }
    window.openModal("Media report",'<div style="font-size:13px">Which items should the report list?</div><div class="mini-row" style="margin-top:12px"><button type="button" class="chip" id="rpAll">Everything ('+all.length+')</button><button type="button" class="chip" id="rpSh">Only shown ('+sh.length+')</button></div>');
    document.getElementById("rpAll").onclick=function(){ try{ window.closeModal(); }catch(e){} download(all,"everything"); };
    document.getElementById("rpSh").onclick=function(){ try{ window.closeModal(); }catch(e){} download(sh,"shown only"); };
  };
  function ensure(){
    var bar=document.querySelector("#leftPanel .md-bar"); if(!bar||document.getElementById("impRepBtn")) return;
    var host=document.getElementById("impLinkBtn"), b=document.createElement("button"); b.type="button"; b.id="impRepBtn"; b.className="chip"; b.textContent="📄 Report"; b.title="Save a spreadsheet of your media"; b.onclick=window.amiyoImpReport;
    if(host&&host.parentNode) host.parentNode.appendChild(b); else { var row=document.createElement("div"); row.className="md-row"; row.appendChild(b); bar.appendChild(row); }
  }
  var lp=document.getElementById("leftPanel"), busy=false;
  if(lp) new MutationObserver(function(){ if(busy) return; busy=true; setTimeout(function(){ try{ ensure(); }catch(e){ window.__swl&&window.__swl(e); } busy=false; },180); }).observe(lp,{childList:true,subtree:true});
  var oc=window.commandList;
  if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Export media report (CSV)","amiyoImpReport()"]]); };
})();

