/* ==================== Script 779 id="amiyo-imp22-storage" ==================== */
/* Import step 22: storage meter at the top of Media. Shows "42 items · 1.8 GB in this session" and, when the browser reports it, how much of the device's
   storage allowance this site uses (navigator.storage.estimate). Turns amber at 70% and red at 90% with a plain hint to remove unused media. Tap it for a breakdown
   by type and the 5 biggest files. Command palette: "Storage use". */
(function(){
  if(window.__amiyoImp22) return; window.__amiyoImp22=true;
  function sz(b){ b=+b||0; return b>=1073741824?(b/1073741824).toFixed(2)+" GB":b>=1048576?(b/1048576).toFixed(1)+" MB":Math.max(1,Math.round(b/1024))+" KB"; }
  function esc(s){ return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];}); }
  var est=null, estAt=0;
  async function estimate(){ if(Date.now()-estAt<15000) return est; estAt=Date.now(); try{ if(navigator.storage&&navigator.storage.estimate){ var e=await navigator.storage.estimate(); est=(e&&e.quota)?e:null; } }catch(x){ est=null; } return est; }
  function stats(){
    var t={video:[0,0],audio:[0,0],image:[0,0]}, all=[], tot=0;
    Object.keys(project.assets||{}).forEach(function(k){ var a=project.assets[k]; if(!a) return; var s=+a.size||0; (t[a.type]||(t[a.type]=[0,0]))[0]++; t[a.type][1]+=s; tot+=s; all.push(a); });
    all.sort(function(x,y){ return (+y.size||0)-(+x.size||0); });
    return {t:t,tot:tot,n:all.length,top:all.slice(0,5)};
  }
  async function paint(){
    var bar=document.querySelector("#leftPanel .md-bar"); if(!bar) return;
    var el=document.getElementById("impStore");
    if(!el){ el=document.createElement("button"); el.type="button"; el.id="impStore"; el.className="chip"; el.style.cssText="width:100%;text-align:left;font-size:11.5px"; el.onclick=window.amiyoImpStorage; bar.insertBefore(el,bar.firstChild); }
    var s=stats(), e=await estimate(), txt=s.n+" item"+(s.n===1?"":"s")+" · "+sz(s.tot), col="";
    if(e&&e.quota){ var p=e.usage/e.quota; txt+=" · site storage "+sz(e.usage)+" of "+sz(e.quota)+" ("+Math.round(p*100)+"%)"; if(p>=.9) col="#ff6b7d"; else if(p>=.7) col="#ffcf70"; }
    if(el.textContent!==txt) el.textContent=txt; el.style.color=col; el.style.borderColor=col||""; el.title=col?"Storage is getting full. Remove unused media or export and clear old projects.":"Tap for a breakdown";
  }
  window.amiyoImpStorage=async function(){
    var s=stats(), e=await estimate();
    window.openModal("Storage use",'<table class="impTbl" style="width:100%;font-size:12.5px;border-collapse:collapse">'+
      ["video","audio","image"].map(function(k){ var x=s.t[k]||[0,0]; return '<tr><td style="padding:5px 4px">'+k[0].toUpperCase()+k.slice(1)+'</td><td>'+x[0]+' files</td><td style="text-align:right">'+sz(x[1])+'</td></tr>'; }).join("")+
      '<tr><td style="padding:5px 4px;border-top:1px solid rgba(255,255,255,.15)"><b>Total</b></td><td style="border-top:1px solid rgba(255,255,255,.15)">'+s.n+' files</td><td style="text-align:right;border-top:1px solid rgba(255,255,255,.15)"><b>'+sz(s.tot)+'</b></td></tr></table>'+
      (e?'<div style="font-size:12.5px;margin-top:10px">Site storage on this device: '+sz(e.usage)+' of about '+sz(e.quota)+'</div>':'<div style="font-size:12px;opacity:.7;margin-top:10px">This browser does not report a storage allowance.</div>')+
      (s.top.length?'<div style="font-size:12px;opacity:.7;margin:10px 0 3px">Biggest files</div>'+s.top.map(function(a){ return '<div style="font-size:12.5px;display:flex;justify-content:space-between;gap:8px"><span style="word-break:break-all">'+esc(a.name)+'</span><span>'+sz(a.size)+'</span></div>'; }).join(""):""));
  };
  var lp=document.getElementById("leftPanel"), busy=false;
  if(lp) new MutationObserver(function(){ if(busy) return; busy=true; setTimeout(function(){ try{ paint(); }catch(e){ window.__swl&&window.__swl(e); } busy=false; },200); }).observe(lp,{childList:true,subtree:true});
  var oc=window.commandList;
  if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Storage use","amiyoImpStorage()"]]); };
})();

;
/* ==================== Script 780 id="amiyo-imp23-reread" ==================== */
/* Import step 23: re-read file info, like Premiere's "Refresh" of media metadata. Files imported before step 6, or whose info could not be read,
   show no codec / frame rate. Media panel > "🔄 Re-read info (N)" reads them again from the files that are online (one at a time, with progress).
   Command palette: "Re-read media info (all online files)" redoes every file. */
(function(){
  if(window.__amiyoImp23) return; window.__amiyoImp23=true;
  var running=false;
  function blob(id){ try{ return ASSET_BLOBS.get(id)||null; }catch(e){ return null; } }
  function todo(all){
    return Object.keys(project.assets||{}).filter(function(k){ var a=project.assets[k]; if(!a||!blob(k)) return false; var m=a.meta; return all||!m||!(m.container||m.videoCodec||m.audioCodec); });
  }
  async function go(all){
    if(running) return; if(typeof window.amiyoImpAnalyse!=="function"){ window.toast&&window.toast("File info reader is not available"); return; }
    var ids=todo(all); if(!ids.length){ window.toast&&window.toast("All online files already have their info"); return; }
    running=true; var done=0, fail=0;
    for(var i=0;i<ids.length;i++){
      var a=project.assets[ids[i]], f=blob(ids[i]); if(!a||!f) continue;
      window.toast&&window.toast("Reading file info "+(i+1)+" of "+ids.length+"…",1500);
      try{ a.meta=await window.amiyoImpAnalyse(f,a); done++; }catch(e){ fail++; window.__swl&&window.__swl(e); }
      if(i%4===3){ try{ renderLeftPanel(); }catch(e){} }
    }
    running=false; try{ scheduleAutosave(); renderLeftPanel(); }catch(e){}
    window.toast&&window.toast(done+" file"+(done===1?"":"s")+" read"+(fail?", "+fail+" failed":""),3500);
  }
  window.amiyoImpReread=go;
  function ensure(){
    var bar=document.querySelector("#leftPanel .md-bar"); if(!bar) return;
    var n=todo(false).length, b=document.getElementById("impRereadBtn");
    if(!n){ if(b&&b.parentNode) b.remove(); return; }
    if(!b){ b=document.createElement("button"); b.type="button"; b.id="impRereadBtn"; b.className="chip"; b.onclick=function(){ go(false); };
      var host=document.getElementById("impLinkBtn"); if(host&&host.parentNode) host.parentNode.appendChild(b); else { var row=document.createElement("div"); row.className="md-row"; row.appendChild(b); bar.appendChild(row); } }
    var t="🔄 Re-read info ("+n+")"; if(b.textContent!==t) b.textContent=t; b.title="Read codec, frame rate and more for files that have no info yet";
  }
  var lp=document.getElementById("leftPanel"), busy=false;
  if(lp) new MutationObserver(function(){ if(busy||running) return; busy=true; setTimeout(function(){ try{ ensure(); }catch(e){ window.__swl&&window.__swl(e); } busy=false; },190); }).observe(lp,{childList:true,subtree:true});
  var oc=window.commandList;
  if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Re-read media info (all online files)","amiyoImpReread(true)"]]); };
})();

