      if(!b){ b=document.createElement("button"); b.type="button"; b.className="imp-pin"; b.textContent="📌"; b.onclick=function(e){ e.stopPropagation(); e.preventDefault(); toggle(el.dataset.asset); }; b.ondblclick=function(e){ e.stopPropagation(); }; el.appendChild(b); }
