      var html=""; badges.forEach(function(fn){ try{ var r=fn(a); if(!r) return; if(typeof r==="string") r=[r,""]; html+='<i title="'+esc(r[1]||"")+'">'+esc(r[0])+'</i>'; }catch(e){} });
      var box=meta.querySelector(".imp2-bdg");
      if(!html){ if(box) box.remove(); return; }
      if(!box){ box=document.createElement("div"); box.className="imp2-bdg"; var more=meta.querySelector(".imp2-more"); if(more) meta.insertBefore(box,more); else meta.appendChild(box); }
      if(box.dataset.h!==html){ box.innerHTML=html; box.dataset.h=html; }
