/* ==================== Script 790 id="amiyo-imp2-04" ==================== */
/* Import 2, step 4/20 (step141): loudness check and normalised copy, like Premiere's Essential Sound > Loudness and "Match Loudness".
   ⋯ More > "Check loudness" measures the average level (dB) and loudest peak of a video's or sound file's audio and says in plain words: too quiet, fine, or very loud / may clip.
   Quiet and loud files get a 🔈 / 🔊 badge on the card. "Make a normalised copy" then writes a new WAV in Media at the level you pick
   (Speech -16 dB, Music/Video -14 dB, or Quiet room -20 dB) without ever going over the peak limit. Your original is not changed.
   Import tools > "Check loudness of everything" measures all sound one by one. (The editor's clip volume can only turn sound down, so a normalised copy is the way to lift quiet files.) */
(function(){
  "use strict";
  if(window.__amiyoImp2s4||!window.amiyoImp2) return; window.__amiyoImp2s4=true;
  var I=window.amiyoImp2, esc=I.esc, MAXB=150*1048576, busy=false;
  function db(x){ return x>1e-7?20*Math.log10(x):-120; }
  async function decode(a){
    var f=I.file(a); if(!f) throw new Error("This file is offline. Relink it first.");
    if(f.size>MAXB) throw new Error("This file is too big to analyse here (over 150 MB).");
    var ab=await f.arrayBuffer(), OC=window.OfflineAudioContext||window.webkitOfflineAudioContext, ctx=new OC(2,2,44100);
    try{ return await new Promise(function(ok,no){ var p=ctx.decodeAudioData(ab,ok,no); if(p&&p.then) p.then(ok,no); }); }
    catch(e){ throw new Error("No sound this browser can read in “"+a.name+"”."); }
  }
  function measure(buf){
    var peak=0, sum=0, cnt=0, ch=buf.numberOfChannels;
    for(var c=0;c<ch;c++){ var d=buf.getChannelData(c); for(var i=0;i<d.length;i++){ var v=d[i], m=v<0?-v:v; if(m>peak) peak=m; if(m>0.001){ sum+=v*v; cnt++; } } }
    return {rms:cnt?db(Math.sqrt(sum/cnt)):-120, peak:db(peak), len:buf.duration};
  }
  async function check(a,quiet){
    var b=await decode(a), m=measure(b); a.loud={rms:Math.round(m.rms*10)/10,peak:Math.round(m.peak*10)/10}; scheduleAutosave();
    try{ renderAll(); }catch(e){} if(!quiet) verdict(a); return m;
  }
  function word(l){ return l.peak>-0.3?["Very loud — may clip (distort)","bad"]:l.rms<-34?["Very quiet","bad"]:l.rms<-26?["A little quiet","warn"]:l.rms>-10?["Very loud","warn"]:["Level looks fine","ok"]; }
  function verdict(a){
    var l=a.loud, w=word(l);
    I.sheet("Loudness",'<table class="impTbl"><tr><td>Average level</td><td><b>'+l.rms+' dB</b></td></tr><tr><td>Loudest peak</td><td><b>'+l.peak+' dB</b></td></tr><tr><td>Verdict</td><td><b>'+w[0]+'</b></td></tr></table>'+
      '<p style="font-size:12px;opacity:.7;margin:8px 0">Speech sounds best around −16 dB average with peaks under −1 dB. Music and video are often −14 dB.</p>'+
      '<div class="mini-row"><button type="button" class="chip" id="i4Norm" style="background:var(--accent);color:#1a0c03;font-weight:700">Make a normalised copy…</button><button type="button" class="chip" id="i4Cl">Close</button></div>');
    document.getElementById("i4Cl").onclick=function(){ window.closeModal(); };
    document.getElementById("i4Norm").onclick=function(){ window.closeModal(); setTimeout(function(){ normaliseDialog(a); },30); };
  }
  function normaliseDialog(a){
    var l=a.loud||{rms:-23,peak:-3};
    I.sheet("Normalised copy",'<label class="field" for="i4T">Target level</label><select id="i4T" style="width:100%"><option value="-16">Speech: −16 dB</option><option value="-14">Music / video: −14 dB</option><option value="-20">Quiet room: −20 dB</option></select>'+
      '<p id="i4Msg" style="font-size:12.5px;margin:10px 0"></p><div class="mini-row"><button type="button" class="chip" id="i4Go" style="background:var(--accent);color:#1a0c03;font-weight:700">Make copy</button><button type="button" class="chip" id="i4No">Cancel</button></div>');
    var $=function(i){return document.getElementById(i);};
    function gain(){ var t=+$("i4T").value, g=t-l.rms, lim=-1-l.peak; return Math.min(g,lim); }
    function msg(){ var g=gain(); $("i4Msg").textContent=Math.abs(g)<.5?"Already close to this level. A copy would sound the same.":"Will change the level by "+(g>0?"+":"")+(Math.round(g*10)/10)+" dB"+(gain()<(+$("i4T").value-l.rms)-.05?" (held back so the peaks do not distort).":"."); }
    $("i4T").onchange=msg; msg(); $("i4No").onclick=function(){ window.closeModal(); };
    $("i4Go").onclick=function(){ var g=gain(); window.closeModal(); make(a,g); };
  }
  function wav(buf,k){
    var n=buf.length, sr=buf.sampleRate, out=new DataView(new ArrayBuffer(44+n*4)), o=0, L=buf.getChannelData(0), R=buf.numberOfChannels>1?buf.getChannelData(1):L;
    function s(t){ for(var i=0;i<t.length;i++) out.setUint8(o++,t.charCodeAt(i)); }
    s("RIFF"); out.setUint32(o,36+n*4,true); o+=4; s("WAVEfmt "); out.setUint32(o,16,true); o+=4; out.setUint16(o,1,true); o+=2; out.setUint16(o,2,true); o+=2; out.setUint32(o,sr,true); o+=4; out.setUint32(o,sr*4,true); o+=4; out.setUint16(o,4,true); o+=2; out.setUint16(o,16,true); o+=2; s("data"); out.setUint32(o,n*4,true); o+=4;
    for(var i=0;i<n;i++){ var l=Math.max(-1,Math.min(1,L[i]*k)), r=Math.max(-1,Math.min(1,R[i]*k)); out.setInt16(o,l<0?l*32768:l*32767,true); o+=2; out.setInt16(o,r<0?r*32768:r*32767,true); o+=2; }
    return new Blob([out],{type:"audio/wav"});
  }
  async function make(a,g){
    if(busy) return; busy=true; window.toast&&window.toast("Making the normalised copy…",20000);
    try{
      var b=await decode(a), base=a.name.replace(/\.[A-Za-z0-9]{2,5}$/,"").replace(/ \((audio|normalised)\)$/,""), file=new File([wav(b,Math.pow(10,g/20))],base+" (normalised).wav",{type:"audio/wav",lastModified:Date.now()});
      var S=window.amiyoImpSettings, was=S&&S.get("addToTimeline"), before=new Set(Object.keys(project.assets)); if(S) S.set("addToTimeline",false);
      try{ await window.importFiles([file]); } finally { if(S) S.set("addToTimeline",was); }
      Object.keys(project.assets).forEach(function(k){ if(!before.has(k)){ var n=project.assets[k]; n.extractedFrom=a.id; if(a.binId) n.binId=a.binId; } });
      scheduleAutosave(); try{ renderAll(); }catch(e){}
      window.toast&&window.toast("Saved “"+file.name+"” in Media ("+(g>0?"+":"")+(Math.round(g*10)/10)+" dB)",5000);
    }catch(e){ window.toast&&window.toast(e&&e.message||String(e),6000); }
    busy=false;
  }
  I.addBadge(function(a){ if(!a.loud) return null; var w=word(a.loud); return w[1]==="ok"?null:[a.loud.peak>-0.3?"🔊 clips":a.loud.rms<-26?"🔈 quiet":"🔊 loud",w[0]+" ("+a.loud.rms+" dB average, "+a.loud.peak+" dB peak)"]; });
  var has=function(a){ return a.type==="video"||a.type==="audio"; };
  I.addAction({id:"loud",label:"Check loudness",hint:"Average level and peak, in plain words",show:has,run:function(a){ if(a.loud) return verdict(a); return check(a).catch(function(e){ window.toast&&window.toast(e.message,6000); }); }});
  I.addAction({id:"loudnorm",label:"Make a normalised copy…",hint:"New WAV at a steady level",show:has,run:function(a){ if(a.loud) return normaliseDialog(a); return check(a,true).then(function(){ normaliseDialog(a); }).catch(function(e){ window.toast&&window.toast(e.message,6000); }); }});
  I.addTool({id:"loudall",label:"Check loudness of everything",hint:"All video and sound, one by one",run:async function(){
    var list=Object.values(project.assets).filter(function(a){ return has(a)&&!a.loud&&I.file(a); }), bad=0, i=0;
    if(!list.length){ window.toast&&window.toast("Everything is already measured",3000); return; }
    for(;i<list.length;i++){ window.toast&&window.toast("Measuring "+(i+1)+" of "+list.length+"…",8000); try{ await check(list[i],true); if(word(list[i].loud)[1]!=="ok") bad++; }catch(e){ list[i].loud=null; } }
    window.toast&&window.toast(list.length+" measured — "+(bad?bad+" need attention (see 🔈 / 🔊 badges)":"all levels look fine"),5000);
  }});
  I.decodeAudio=decode;
  try{ window.AMIYO_EDITOR_BUILD="import2-step04"; }catch(e){}
})();

