/* ==================== Script 791 id="amiyo-imp2-05" ==================== */
/* Import 2, step 5/20 (step142): footage check, like Premiere's warnings for phone video and HDR.
   After import, MP4 / MOV / M4V files are read at the "movie header" level (nothing is decoded) to find the things that make editing go wrong:
   variable frame rate (typical for phone screen recordings and some phone cameras: cuts can drift out of sync), rotated phone video, HDR (HLG / PQ / Dolby Vision: colours can look flat), and video with no sound track.
   Cards show small badges (〰 VFR, ↻ 90°, HDR, 🔇). ⋯ More > "Footage check" explains each one in plain words with the fix, including a copy-ready ffmpeg line to make it constant frame rate. */
(function(){
  "use strict";
  if(window.__amiyoImp2s5||!window.amiyoImp2) return; window.__amiyoImp2s5=true;
  var I=window.amiyoImp2, esc=I.esc;
  function t4(dv,o){ return String.fromCharCode(dv.getUint8(o),dv.getUint8(o+1),dv.getUint8(o+2),dv.getUint8(o+3)); }
  function boxes(dv,s,e,fn){
    var p=s; while(p+8<=e){ var sz=dv.getUint32(p), ty=t4(dv,p+4), hd=8; if(sz===1){ sz=dv.getUint32(p+12); hd=16; } else if(sz===0) sz=e-p; if(sz<hd||p+sz>e+0) { if(p+sz>e) sz=e-p; if(sz<hd) break; } fn(ty,p+hd,p+sz,p); p+=sz; }
  }
  function parseMoov(dv,s,e){
    var res={tracks:[]};
    boxes(dv,s,e,function(ty,bs,be){
      if(ty!=="trak") return; var tr={kind:"",rot:0,deltas:[],fmt:"",colr:null};
      (function walk(a,b){ boxes(dv,a,b,function(t,x,y){
        if(t==="mdia"||t==="minf"||t==="stbl") return walk(x,y);
        if(t==="tkhd"){ var v=dv.getUint8(x), m=x+(v===1?52:40); try{ var A=dv.getInt32(m)/65536, B=dv.getInt32(m+4)/65536; tr.rot=Math.round(Math.atan2(B,A)*180/Math.PI); if(tr.rot<0) tr.rot+=360; }catch(e){} }
        else if(t==="hdlr"){ tr.kind=t4(dv,x+8); }
        else if(t==="mdhd"){ var vv=dv.getUint8(x); tr.ts=dv.getUint32(x+(vv===1?20:12)); }
        else if(t==="stts"){ var n=dv.getUint32(x+4), lim=Math.min(n,4000); for(var i=0;i<lim;i++){ var o=x+8+i*8; if(o+8>y) break; tr.deltas.push([dv.getUint32(o),dv.getUint32(o+4)]); } tr.sttsN=n; }
        else if(t==="stsd"){ var q=x+8; if(q+16<=y){ tr.fmt=t4(dv,q+4); for(var k=q+8;k<Math.min(y-12,q+400);k++){ if(t4(dv,k)==="colr"&&t4(dv,k+4)==="nclx"){ tr.colr={p:dv.getUint16(k+8),t:dv.getUint16(k+10),m:dv.getUint16(k+12)}; break; } } } }
      }); })(bs,be);
      res.tracks.push(tr);
    });
    return res;
  }
  async function readMoov(f){
    var pos=0, size=f.size, guard=0;
    while(pos+8<=size&&guard++<200){
      var h=new DataView(await f.slice(pos,pos+16).arrayBuffer()), sz=h.getUint32(0), ty=t4(h,4);
      if(sz===1) sz=h.getUint32(12); else if(sz===0) sz=size-pos;
      if(sz<8) return null;
      if(ty==="moov"){ if(sz>24*1048576) return null; var b=new DataView(await f.slice(pos,pos+sz).arrayBuffer()); return parseMoov(b,8,b.byteLength); }
      pos+=sz;
    }
    return null;
  }
  async function check(f){
    if(!/\.(mp4|m4v|mov|3gp)$/i.test(f.name)&&!/^video\/(mp4|quicktime)/.test(f.type)) return null;
    var m=await readMoov(f); if(!m) return null;
    var v=m.tracks.filter(function(t){return t.kind==="vide";})[0], au=m.tracks.some(function(t){return t.kind==="soun";});
    if(!v) return null;
    var out={noAudio:!au};
    if(v.rot) out.rot=v.rot;
    if(v.deltas.length>1){ var tot=0,mx=0; v.deltas.forEach(function(d){ tot+=d[0]; if(d[0]>mx) mx=d[0]; }); if(tot>10&&mx/tot<.97&&v.deltas.length>3) out.vfr=true; }
    if(v.colr&&(v.colr.t===16||v.colr.t===18)) out.hdr=v.colr.t===18?"HLG":"PQ"; else if(/^dv|^dav/.test(v.fmt)) out.hdr="Dolby Vision";
    return out;
  }
  async function fill(max){
    var n=0; for(var k in project.assets){ var a=project.assets[k]; if(a.fcTried||a.type!=="video") continue; var f=I.file(a); if(!f) continue; a.fcTried=1;
      try{ var r=await check(f); if(r) a.fc=r; }catch(e){ window.__swl&&window.__swl(e); } n++; if(n>=max) break; }
    return n;
  }
  var inner=window.importFiles;
  window.importFiles=async function(){ var r=await inner.apply(this,arguments); try{ if(await fill(60)){ scheduleAutosave(); try{ renderAll(); }catch(e){} } }catch(e){ window.__swl&&window.__swl(e); } return r; };
  var lp=document.getElementById("leftPanel"), busy=false;
  if(lp) new MutationObserver(function(){ if(busy) return; busy=true; setTimeout(async function(){ try{ if(await fill(6)) scheduleAutosave(); }catch(e){} busy=false; },400); }).observe(lp,{childList:true,subtree:true});
  I.addBadge(function(a){ var c=a.fc; if(!c) return null; var r=[]; if(c.vfr) r.push("〰 VFR"); if(c.rot) r.push("↻ "+c.rot+"°"); if(c.hdr) r.push("HDR"); if(c.noAudio) r.push("🔇"); return r.length?[r.join(" "),"Footage check: tap ⋯ More > Footage check"]:null; });
  function cmd(a){ var b=a.name.replace(/\.[A-Za-z0-9]{2,5}$/,""); return 'ffmpeg -i "'+a.name+'" -vf fps='+(Math.round((a.fps||(a.meta&&a.meta.fps)||30)))+' -c:v libx264 -crf 18 -c:a copy "'+b+'_cfr.mp4"'; }
  I.addAction({id:"fcheck",label:"Footage check",hint:"Variable frame rate, rotation, HDR, no sound",show:function(a){ return a.type==="video"; },run:async function(a){
    if(!a.fc&&!a.fcTried){ a.fcTried=1; var f=I.file(a); if(f){ try{ var r=await check(f); if(r) a.fc=r; }catch(e){} } }
    var c=a.fc, rows=[];
    if(!c){ rows.push(["Not an MP4 / MOV file, or its header could not be read","The check works for phone and camera files (.mp4, .mov, .m4v). Nothing is wrong that we can see."]); }
    else {
      if(c.vfr) rows.push(["〰 Variable frame rate","The picture does not keep a steady frame rate (common with screen recordings and some phone cameras). Cuts and sound can drift apart on long clips. Fix: convert to a constant frame rate before editing."]);
      if(c.rot) rows.push(["↻ Rotated "+c.rot+"°","The file is stored sideways and turned on playback. The editor shows it correctly in most browsers; if a clip looks sideways, use Rotation in Inspect."]);
      if(c.hdr) rows.push(["HDR ("+c.hdr+")","Colours can look flat or washed out here and in the exported file. Fix: convert to SDR (Rec.709) before editing."]);
      if(c.noAudio) rows.push(["🔇 No sound track","This video has no audio. That is fine for b-roll."]);
      if(!rows.length) rows.push(["Looks good","Constant frame rate, upright, standard colour, with sound."]);
    }
    var h='<div style="font-size:12.5px">'+rows.map(function(r){ return '<div style="margin:0 0 10px"><b>'+esc(r[0])+'</b><br><span style="opacity:.8">'+esc(r[1])+'</span></div>'; }).join("")+'</div>';
    if(c&&c.vfr) h+='<div style="font-size:11.5px;opacity:.7;margin-bottom:4px">Copy this ffmpeg line:</div><textarea readonly style="width:100%;height:64px;font:11px monospace" id="i5Cmd">'+esc(cmd(a))+'</textarea><div class="mini-row" style="margin-top:6px"><button type="button" class="chip" id="i5Cp">Copy</button></div>';
    I.sheet("Footage check",h);
    var b=document.getElementById("i5Cp"); if(b) b.onclick=function(){ var t=document.getElementById("i5Cmd"); try{ navigator.clipboard.writeText(t.value); }catch(e){ t.select(); document.execCommand("copy"); } window.toast&&window.toast("Copied",2000); };
  }});
  I.addTool({id:"fcall",label:"Footage check for all videos",hint:"Lists the files with VFR, HDR or sideways video",run:async function(){
    for(var k in project.assets) delete project.assets[k].fcTried; await fill(500); scheduleAutosave(); try{ renderAll(); }catch(e){}
    var bad=Object.values(project.assets).filter(function(a){ return a.fc&&(a.fc.vfr||a.fc.hdr||a.fc.rot); });
    I.sheet("Footage check",bad.length?'<div style="font-size:12.5px;max-height:50vh;overflow:auto">'+bad.map(function(a){ var c=a.fc, r=[]; if(c.vfr) r.push("variable frame rate"); if(c.hdr) r.push("HDR "+c.hdr); if(c.rot) r.push("rotated "+c.rot+"°"); return '<div style="margin:6px 0"><b>'+esc(a.name)+'</b><br><span style="opacity:.75">'+r.join(", ")+'</span></div>'; }).join("")+'</div>':'<p>No problems found in your MP4 / MOV videos.</p>');
  }});
  I.footageCheck=check;
  try{ window.AMIYO_EDITOR_BUILD="import2-step05"; }catch(e){}
})();

