/* ==================== Script 792 id="amiyo-imp2-06" ==================== */
/* Import 2, step 6/20 (step143): add only the picture, only the sound, or both on separate tracks, like Premiere's "Drag Video Only / Drag Audio Only" in the Source Monitor.
   ⋯ More on a video card: "Add picture only (muted)", "Add sound only (audio track)", "Add picture + sound on separate tracks (linked)".
   Clips go in at the playhead in the first free place, honour Interpret footage (step 2), and are one step in Undo. The linked pair works with the editor's existing "Re-attach audio". */
(function(){
  "use strict";
  if(window.__amiyoImp2s6||!window.amiyoImp2) return; window.__amiyoImp2s6=true;
  var I=window.amiyoImp2;
  function audioTrackFor(s,e){
    var tr=project.tracks.filter(function(t){ return t.kind==="audio"&&!t.locked; });
    for(var i=0;i<tr.length;i++){ var t=tr[i]; if(!t.clips.some(function(o){ return o.start<e-0.0005&&o.start+o.duration>s+0.0005; })) return t; }
    var n=project.tracks.filter(function(t){ return t.kind==="audio"; }).length+1;
    var nt={id:uid("track"),name:"Audio "+n,kind:"audio",locked:false,hidden:false,muted:false,clips:[]};
    var at=project.tracks.map(function(t){ return t.kind; }).lastIndexOf("audio"); project.tracks.splice(at+1,0,nt);
    return nt;
  }
  function mk(a,start,dur,src,f){ return {id:uid("clip"),assetId:a.id,start:start,duration:dur,inPoint:0,outPoint:src,volume:1,opacity:1,speed:f,rotation:0,scale:1,x:.5,y:.5,trimL:0,trimR:0,fit:"contain",effects:[],keyframes:[],transitionIn:null,transitionOut:null}; }
  function place(a,mode){
    var b=deepClone(serializableProject()), f=(a.interp&&a.interp.speed)||1, src=Math.max(.5,a.duration||5), dur=src/f, label, sel=null;
    if(mode==="audio"){
      var at=audioTrackFor(currentTime,currentTime+dur), s=nearestGap(at.clips,currentTime,dur), ac=mk(a,s,dur,src,f); ac.name=a.name; at.clips.push(ac); at.clips.sort(function(x,y){return x.start-y.start;}); sel=[ac,at]; label="Add sound only";
    } else {
      var vt=getTrack("video"), s2=nearestGap(vt.clips,currentTime,dur), vc=mk(a,s2,dur,src,f); vc.volume=0; vt.clips.push(vc); vt.clips.sort(function(x,y){return x.start-y.start;}); sel=[vc,vt]; label="Add picture only";
      if(mode==="both"){
        var t2=audioTrackFor(s2,s2+dur), ac2=mk(a,s2,dur,src,f), lid=uid("link"); ac2.name=a.name; ac2.linkId=lid; ac2.detachedFrom=vc.id; vc.linkId=lid; vc.audioDetached=ac2.id; t2.clips.push(ac2); t2.clips.sort(function(x,y){return x.start-y.start;}); label="Add picture + sound";
      }
    }
    selectedClipId=sel[0].id; selectedTrackId=sel[1].id;
    try{ recordHistory(label,b,serializableProject()); updateUndoRedo(); }catch(e){ window.__swl&&window.__swl(e); }
    scheduleAutosave(); renderAll(); window.toast&&window.toast(label+" — added at the playhead",3000);
  }
  var vid=function(a){ return a.type==="video"; };
  I.addAction({id:"addv",label:"Add picture only (muted)",hint:"Video without its sound",show:vid,run:function(a){ place(a,"video"); }});
  I.addAction({id:"adda",label:"Add sound only (audio track)",hint:"Just the sound of this video",show:vid,run:function(a){ place(a,"audio"); }});
  I.addAction({id:"addb",label:"Add picture + sound on separate tracks",hint:"Linked pair, easy to edit apart",show:vid,run:function(a){ place(a,"both"); }});
  I.placeAsset=place;
  try{ window.AMIYO_EDITOR_BUILD="import2-step06"; }catch(e){}
})();

