/* ==================== Script 797 id="amiyo-v118-audio-selftest" ==================== */
/* Step 119-02: "Check all sounds" in the Audio panel. Renders every built-in sound effect and music bed in small batches and marks each one
   OK or with the problem found (silent, clipped, broken numbers, wrong length). Marks stay on the rows while you search or switch tabs. */
(function(){
  "use strict";
  var SR=44100, H=window.__auHealth=window.__auHealth||{}, running=false;
  function all(){ var A=window.AMIYO_AUDIO; return A?(A.sfx||[]).map(function(d){return{d:d,k:"sfx"};}).concat((A.beds||[]).map(function(d){return{d:d,k:"bed"};})):[]; }
  function test(it){
    var d=it.d, bad=[];
    try{
      var f=d.gen(), pk=0, sq=0, nan=0, i, v;
      for(i=0;i<f.length;i++){ v=f[i]; if(v!==v||v===Infinity||v===-Infinity){ nan++; continue; } if(v<0)v=-v; if(v>pk)pk=v; sq+=v*v; }
      var rms=Math.sqrt(sq/Math.max(1,f.length)), dur=f.length/SR;
      if(!f.length) bad.push("empty");
      if(nan) bad.push("broken samples");
      if(pk<.02||rms<.003) bad.push("silent");
      if(pk>1.001) bad.push("clips");
      if(dur<.05) bad.push("too short");
      var A=window.AMIYO_AUDIO, pool=A?[].concat(A.sfx||[],A.beds||[]):[], same=0, sn=0;
      for(var k=0;k<pool.length;k++){ if(pool[k]&&pool[k].id===d.id) same++; if(pool[k]&&String(pool[k].name).toLowerCase()===String(d.name).toLowerCase()) sn++; }
      if(same>1) bad.push("id shared with another sound");
      if(sn>1) bad.push("name repeated");
      if(typeof d.gen!=="function"||!d.id) bad.push("incomplete entry");
      return {ok:!bad.length,msg:bad.length?bad.join(", "):"OK \u00b7 "+(Math.round(dur*100)/100)+" s"};
    }catch(e){ return {ok:false,msg:"fails to render: "+((e&&e.message)||e)}; }
  }
  function mark(){
    var lp=document.getElementById("leftPanel"); if(!lp) return;
    var rows=lp.querySelectorAll(".au-row [data-play]");
    for(var i=0;i<rows.length;i++){
      var id=rows[i].getAttribute("data-play"), h=H[id], nm=rows[i].parentNode.querySelector(".au-name"); if(!nm) continue;
      var old=nm.querySelector(".au-h"); if(!h){ if(old) old.remove(); continue; }
      if(!old){ old=document.createElement("i"); old.className="au-h"; old.style.cssText="font-style:normal;font-size:10px"; nm.appendChild(old); }
      old.textContent=(h.ok?"\u2713 ":"\u26a0 ")+h.msg; old.style.color=h.ok?"#3fb97a":"#e5984a";
    }
  }
  function inject(){
    var tabs=document.getElementById("auTabs"); if(!tabs||document.getElementById("auCheck")) { mark(); return; }
    var card=tabs.parentNode, box=document.createElement("div"); box.style.marginTop="8px";
    box.innerHTML='<button type="button" class="chip" id="auCheck">Check all sounds</button> <span id="auCheckOut" role="status" style="font-size:10px;color:var(--muted)"></span>';
    card.appendChild(box); summary(); mark();
    document.getElementById("auCheck").onclick=run;
  }
  function summary(){
    var out=document.getElementById("auCheckOut"); if(!out) return;
    var L=all(), n=0, b=0; L.forEach(function(x){ var h=H[x.d.id]; if(h){ n++; if(!h.ok) b++; } });
    out.textContent=n?(b?b+" of "+n+" need attention (marked \u26a0)":"All "+n+" sounds are fine"):"";
  }
  function run(){
    if(running) return; running=true; var L=all(), i=0, btn=document.getElementById("auCheck"), out=document.getElementById("auCheckOut");
    if(btn) btn.disabled=true;
    (function step(){
      var t=Date.now();
      while(i<L.length&&Date.now()-t<40){ H[L[i].d.id]=test(L[i]); i++; }
      var o=document.getElementById("auCheckOut"); if(o) o.textContent="Checking "+i+" of "+L.length+"\u2026";
      mark();
      if(i<L.length){ setTimeout(step,0); return; }
      running=false; var b=document.getElementById("auCheck"); if(b) b.disabled=false; summary(); mark();
      try{ if(window.toast) window.toast("Sound check finished"); }catch(e){}
    })();
  }
  var lp=document.getElementById("leftPanel");
  if(lp){ new MutationObserver(function(){ if(document.getElementById("auTabs")) inject(); }).observe(lp,{childList:true,subtree:true}); }
  if(document.getElementById("auTabs")) inject();
})();

