/* ==================== Script 798 id="amiyo-v120-import-sniff" ==================== */
/* Step 120-03: files whose name has no usable extension (or a wrong one, e.g. "PTT-2026...-WA0001." from WhatsApp) are recognised from their first bytes,
   so voice notes and music no longer land in the Library as broken "images". */
(function(){
  "use strict";
  var IMG=/\.(png|jpe?g|gif|webp|avif|bmp|svg|ico|tiff?|heic|heif)$/i;
  function s4(a,o){ return String.fromCharCode(a[o],a[o+1],a[o+2],a[o+3]); }
  window.amiyoSniffAudio=function(u8){
    if(!u8||u8.length<12) return null;
    var h=s4(u8,0);
    if(h==="OggS"){ var t=""; for(var i=0;i<Math.min(u8.length,128);i++) t+=String.fromCharCode(u8[i]); if(t.indexOf("OpusHead")>=0) return {ext:"opus",mime:"audio/ogg"}; if(t.indexOf("vorbis")>=0) return {ext:"ogg",mime:"audio/ogg"}; return null; }
    if(h==="fLaC") return {ext:"flac",mime:"audio/flac"};
    if(h==="RIFF"&&s4(u8,8)==="WAVE") return {ext:"wav",mime:"audio/wav"};
    if(h==="FORM"&&/AIF[FC]/.test(s4(u8,8))) return {ext:"aiff",mime:"audio/aiff"};
    if(h.slice(0,3)==="ID3") return {ext:"mp3",mime:"audio/mpeg"};
    if(u8[0]===0xFF&&(u8[1]&0xE0)===0xE0){ return (u8[1]&0x06)===0?{ext:"aac",mime:"audio/aac"}:{ext:"mp3",mime:"audio/mpeg"}; }
    if(h==="#!AM") return {ext:"amr",mime:"audio/amr"};
    if(s4(u8,4)==="ftyp"){ var b=s4(u8,8); if(/^(M4A |M4B )/.test(b)) return {ext:"m4a",mime:"audio/mp4"}; }
    return null;
  };
  function wrap(){
    var inner=window.importFiles; if(typeof inner!=="function"||inner.__sniff) return;
    var w=async function(files){
      var list=[].slice.call(files||[]), out=[];
      for(var i=0;i<list.length;i++){
        var f=list[i];
        try{
          var t=(f.type||"").toLowerCase();
          if(f&&f.size>12&&typeof mediaType==="function"&&mediaType(f)==="image"&&t.indexOf("image/")!==0&&!IMG.test(f.name||"")){
            var u8=new Uint8Array(await f.slice(0,160).arrayBuffer()), k=window.amiyoSniffAudio(u8);
            if(k){ var base=String(f.name||"audio").replace(/\.+$/,"").replace(/\.[A-Za-z0-9]{1,5}$/,function(m){ return m; }); f=new File([f],base+"."+k.ext,{type:k.mime,lastModified:f.lastModified}); }
          }
        }catch(e){ window.__swl&&window.__swl(e); }
        out.push(f);
      }
      return inner.call(this,out.length===1&&files&&files.length===undefined?out[0]:out);
    };
    w.__sniff=true; window.importFiles=w;
  }
  wrap();
})();

