/* ==================== Script 800 id="amiyo-v122-playback-guard" ==================== */
/* Step 122-05: reliable timeline audio. (1) The sound system is unlocked on your first tap/key so phones and Safari never start "muted", and is woken
   again if the browser suspends it. (2) A clip whose file the browser rejects is retried with the right audio type, then as a converted copy, instead of
   staying silent. (3) A missing or unplayable audio file shows a message naming the clip, once. (4) An error in one clip can no longer stop the others. */
(function(){
  "use strict";
  function active(){ try{ return !(navigator.userActivation)||navigator.userActivation.hasBeenActive; }catch(e){ return true; } }
  function wake(){
    try{
      if(!active()) return;   /* no sound system before the first real tap/key: avoids the "AudioContext was not allowed to start" warning */
      if(typeof audioContext!=="undefined"&&audioContext){ if(audioContext.state!=="running") audioContext.resume().catch(function(){}); return; }
      if(typeof getAudioContext==="function") getAudioContext().catch(function(){});
    }catch(e){ window.__swl&&window.__swl(e); }
  }
  var unlocked=false;
  function unlock(e){
    if(e&&e.type==="pointerdown"&&e.pointerType&&e.pointerType!=="mouse") return;   /* touch pointerdown is not a user activation; touchend/click follow */
    if(!active()) return;
    wake();
    try{ if(typeof audioContext!=="undefined"&&audioContext&&!unlocked){ var b=audioContext.createBuffer(1,1,22050), s=audioContext.createBufferSource(); s.buffer=b; s.connect(audioContext.destination); s.start(0); unlocked=true; } }catch(e){}
    if(unlocked){ ["pointerdown","touchend","keydown","click"].forEach(function(n){ document.removeEventListener(n,unlock,true); }); }
  }
  ["pointerdown","touchend","keydown","click"].forEach(function(n){ document.addEventListener(n,unlock,true); });
  document.addEventListener("visibilitychange",function(){ if(!document.hidden) wake(); });
  function report(key,title,detail){ try{ if(window.amiyoReportOnce) window.amiyoReportOnce(key,title,detail); else if(window.toast) window.toast(title); }catch(e){} }
  function guard(el,clip){
    if(el.__amiyoG) return; el.__amiyoG=1; var stage=0;
    el.addEventListener("error",async function(){
      if(stage>=2) return; var at=el.currentTime||0, was=!el.paused, name=(typeof getAsset==="function"&&getAsset(clip.assetId)||{}).name||clip.name||"An audio clip";
      try{
        var src=el.currentSrc||el.src, blob=await (await fetch(src)).blob();
        if(stage===0){
          stage=1; var typed=window.amiyoFixAudioType?await window.amiyoFixAudioType(blob,name):blob;
          if(typed!==blob){ el.src=URL.createObjectURL(typed); el.load(); try{ el.currentTime=at; }catch(e){} if(was) el.play().catch(function(){}); return; }
        }
        stage=2; var wav=await window.amiyoDecodeToWav(blob);
        el.src=URL.createObjectURL(wav); el.load(); try{ el.currentTime=at; }catch(e){}
        if(typeof isPlaying!=="undefined"&&isPlaying) el.play().catch(function(){});
      }catch(e){ stage=2; report("aud:"+clip.assetId,"\u201c"+name+"\u201d can't be played","The browser could not decode this audio ("+((e&&e.message)||"unsupported format")+"). Convert it to MP3 or WAV and import it again."); }
    });
  }
  var prevEnsure=window.ensureAudioElement;
  if(typeof prevEnsure==="function") window.ensureAudioElement=async function(clip){
    var el=await prevEnsure.apply(this,arguments);
    try{
      if(el&&clip) guard(el,clip);
      else if(!el&&clip&&typeof getAsset==="function"){ var a=getAsset(clip.assetId); if(a&&a.type==="audio") report("aud-miss:"+a.id,"\u201c"+(a.name||"An audio file")+"\u201d is missing","The audio file is not stored on this device. Re-import it, or use Relink to reconnect it."); }
    }catch(e){ window.__swl&&window.__swl(e); }
    return el;
  };
  var prevUAP=window.updateAudioPlayback;
  if(typeof prevUAP==="function") window.updateAudioPlayback=async function(){
    try{ if(typeof isPlaying!=="undefined"&&isPlaying) wake(); return await prevUAP.apply(this,arguments); }
    catch(e){ try{ console.warn("Audio playback",e); }catch(_){} }
  };
})();

