/* ==================== Script 801 id="amiyo-v123-volume-parity" ==================== */
/* Step 123-06: preview now matches export. Volume automation (the volume line you draw, and "Auto-duck under dialogue") was heard in the export but
   overwritten in the live preview by the mixer's track-volume step, so the preview played at a flat level. The automation is now applied last,
   on top of fades, ducking, track volume, mute/solo and master. An audio file the export cannot decode is now reported instead of silently left out. */
(function(){
  "use strict";
  var prev=window.updateAudioPlayback; if(typeof prev!=="function") return;
  function cl(x){ return x<0?0:x>1?1:x; }
  function fix(){
    if(typeof project==="undefined"||typeof audioEls==="undefined"||typeof currentTime==="undefined") return;
    var vAt=window.volumeAt; if(typeof vAt!=="function") return;
    var anySolo=project.tracks.some(function(t){ return t.kind==="audio"&&t.solo; });
    project.tracks.forEach(function(t){
      if(t.kind!=="audio"||!t.clips) return;
      var muted=t.muted||(anySolo&&!t.solo);
      t.clips.forEach(function(c){
        if(!c.volumeKeyframes||!c.volumeKeyframes.length) return;
        var el=audioEls.get(c.id); if(!el||el.paused) return;
        var local=currentTime-c.start; if(local<0||local>c.duration) return;
        if(muted){ el.volume=0; return; }
        var base=c.volume==null?1:c.volume, target=vAt(c,local);
        if(base>0.001) el.volume=cl(el.volume*target/base);
        else{
          var tv=t.volume==null?1:t.volume, m=window.amiyoMaster?window.amiyoMaster():1, f=window.amiyoFade?window.amiyoFade(c,local):1;
          el.volume=cl(target*tv*f*m);
        }
      });
    });
  }
  window.updateAudioPlayback=async function(){
    var r=await prev.apply(this,arguments);
    try{ fix(); }catch(e){ window.__swl&&window.__swl(e); }
    return r;
  };
})();

