/* ==================== Script 802 id="amiyo-v124-meter-videosound" ==================== */
/* Step 124-07: the master meter was blind to the sound of clips on the VIDEO track (it only listened to audio-track clips), so it stayed flat while
   a video's own sound played. This keeps a list of every sound source that really feeds the speakers (the silent waveform scanner is excluded)
   and the master meter now listens to all of them. */
(function(){
  "use strict";
  if(window.__amiyoLiveSrc||typeof AudioNode==="undefined"||typeof MediaElementAudioSourceNode==="undefined") return;
  var LIVE=window.__amiyoLiveSrc=new Set(), oc=AudioNode.prototype.connect;
  AudioNode.prototype.connect=function(dest){
    try{ if(this instanceof MediaElementAudioSourceNode&&dest&&this.context&&dest===this.context.destination) LIVE.add(this); }catch(e){}
    return oc.apply(this,arguments);
  };
})();

