/* ==================== Script 803 id="amiyo-v126-audio-library-tools" ==================== */
/* Step 126-09: Audio library tools. Star any sound, music bed or imported file (stars are kept on this device; imported files keep theirs in the project),
   show favourites only, search the Music beds and Your audio tabs, and filter music beds by mood. */
(function(){
  "use strict";
  var FKEY="amiyoAudioFavs", MOODS=["All","Chill","Upbeat","Cinematic","Beats"];
  var MOOD={chill:"Chill",pad:"Chill",dream:"Chill",ambient:"Chill",keys:"Chill",space:"Chill",warmkeys:"Chill",softhop:"Chill",bossa:"Chill",jazz:"Chill",waltz:"Chill",
    pulse:"Upbeat",funk:"Upbeat",sunny:"Upbeat",tropical:"Upbeat",bounce:"Upbeat",acoustic:"Upbeat",uplift:"Upbeat",chip:"Upbeat",corporate:"Upbeat",
    epic:"Cinematic",tense:"Cinematic",orchestral:"Cinematic",strings:"Cinematic",anthem:"Cinematic",drone:"Cinematic",
    synthwave:"Beats",trap:"Beats",boombap:"Beats",techno:"Beats"};
  function moodOf(id){ return MOOD[String(id).replace(/-\d+$/,"")]||"Upbeat"; }
  window.amiyoBedMood=moodOf;
  function favs(){ try{ return new Set(JSON.parse(localStorage.getItem(FKEY)||"[]")); }catch(e){ return new Set(); } }
  function saveFavs(s){ try{ localStorage.setItem(FKEY,JSON.stringify(Array.from(s))); }catch(e){} }
  var FAV=favs(), q="", favOnly=false, mood="All", lastTab="", obs=null;
  function asset(id){ return (typeof project!=="undefined"&&project&&project.assets)?project.assets[id]:null; }
  function isFav(id,yours){ if(yours){ var a=asset(id); return !!(a&&a.favorite); } return FAV.has(id); }
  function tabNow(){ var b=document.querySelector("#auTabs .chip.on"); return b?b.getAttribute("data-tab"):"sfx"; }
  function starText(on){ return on?"\u2605":"\u2606"; }
  function toolbar(tab){
    var tabs=document.getElementById("auTabs"); if(!tabs) return;
    if(tab!==lastTab){ lastTab=tab; q=""; mood="All"; }
    var box=document.getElementById("auXtra"); if(box) return;
    box=document.createElement("div"); box.id="auXtra"; box.style.marginTop="8px";
    var h="";
    if(tab!=="sfx") h+='<input type="search" id="auQ2" class="search" placeholder="'+(tab==="music"?"Search music\u2026":"Search your audio\u2026")+'" aria-label="Search" value="'+q.replace(/"/g,"&quot;")+'">';
    h+='<div class="mini-row" style="margin-top:8px"><button type="button" class="chip'+(favOnly?" on":"")+'" data-axf="fav" aria-pressed="'+favOnly+'">\u2605 Favourites</button>';
    if(tab==="music") MOODS.forEach(function(m){ h+='<button type="button" class="chip'+(mood===m?" on":"")+'" data-axm="'+m+'">'+m+'</button>'; });
    h+='</div><div id="auCount" style="font-size:10px;color:var(--muted);margin-top:6px" role="status"></div>';
    box.innerHTML=h; tabs.parentNode.insertBefore(box,tabs.nextSibling);
  }
  function apply(){
    var list=document.getElementById("auList"); if(!list) return;
    var tab=tabNow(), rows=list.querySelectorAll(".au-row"), shown=0, total=0, old=document.getElementById("auNone"); if(old) old.remove();
    var ql=q.trim().toLowerCase();
    for(var i=0;i<rows.length;i++){
      var row=rows[i], p=row.querySelector("[data-play]"), a=row.querySelector("[data-asset]:not([data-yplay])"), id=p?p.getAttribute("data-play"):(a?a.getAttribute("data-asset"):null);
      if(!id) continue; total++;
      var yours=!p, on=isFav(id,yours), st=row.querySelector("[data-fav]");
      if(!st){ st=document.createElement("button"); st.type="button"; st.className="chip au-fav"; st.setAttribute("data-fav",id); st.setAttribute("data-yours",yours?"1":"0"); st.style.minWidth="34px";
        var add=row.querySelector("[data-add],[data-asset]"); row.insertBefore(st,add||null); }
      if(st.textContent!==starText(on)) st.textContent=starText(on); st.setAttribute("aria-label",(on?"Remove from":"Add to")+" favourites"); st.style.color=on?"#f5c542":"";
      var nm=((row.querySelector(".au-name b")||{}).textContent||"").toLowerCase(), show=true;
      if(favOnly&&!on) show=false;
      if(tab!=="sfx"&&ql&&nm.indexOf(ql)<0) show=false;
      if(tab==="music"&&mood!=="All"&&moodOf(id)!==mood) show=false;
      row.style.display=show?"":"none"; if(show) shown++;
    }
    var c=document.getElementById("auCount"); var ct=total?(shown+" of "+total+" shown"):""; if(c&&c.textContent!==ct) c.textContent=ct;
    if(total&&!shown){ var d=document.createElement("div"); d.id="auNone"; d.className="el-empty"; d.textContent=favOnly?"No favourites here yet. Tap \u2606 on a sound to add one.":"Nothing matches."; list.appendChild(d); }
  }
  function render(){
    if(!document.getElementById("auTabs")||!document.getElementById("auList")) return;
    toolbar(tabNow()); apply(); if(obs) obs.takeRecords();
  }
  var lp=document.getElementById("leftPanel"); if(!lp) return;
  var pending=0;
  obs=new MutationObserver(function(){ if(pending) return; pending=1; setTimeout(function(){ pending=0; try{ render(); }catch(e){ window.__swl&&window.__swl(e); } },0); });
  obs.observe(lp,{childList:true,subtree:true});
  lp.addEventListener("click",function(e){
    var f=e.target.closest&&e.target.closest("[data-fav]");
    if(f){ e.preventDefault(); e.stopPropagation(); var id=f.getAttribute("data-fav");
      if(f.getAttribute("data-yours")==="1"){ var a=asset(id); if(a){ a.favorite=!a.favorite; try{ scheduleAutosave(); }catch(x){} } }
      else{ if(FAV.has(id)) FAV.delete(id); else FAV.add(id); saveFavs(FAV); }
      apply(); if(obs) obs.takeRecords(); return; }
    var t=e.target.closest&&e.target.closest("[data-axf]");
    if(t){ favOnly=!favOnly; t.classList.toggle("on",favOnly); t.setAttribute("aria-pressed",String(favOnly)); apply(); if(obs) obs.takeRecords(); return; }
    var m=e.target.closest&&e.target.closest("[data-axm]");
    if(m){ mood=m.getAttribute("data-axm"); var all=document.querySelectorAll("[data-axm]"); for(var i=0;i<all.length;i++) all[i].classList.toggle("on",all[i]===m); apply(); if(obs) obs.takeRecords(); }
  },true);
  lp.addEventListener("input",function(e){ if(e.target&&e.target.id==="auQ2"){ q=e.target.value; apply(); if(obs) obs.takeRecords(); } });
  render();
})();

