/* ==================== Script 805 id="amiyo-a06-import-health" ==================== */
/* Audio step 6: every file in "Your audio" shows whether this browser can play it (\u2713 plays, \u26a0 problem, \u26a0 missing) so a silent import is spotted before it reaches the timeline. */
(function(){
  "use strict";
  var H={}, busy={};
  function blobOf(id){
    try{ var b=(typeof ASSET_BLOBS!=="undefined"&&ASSET_BLOBS.get(id))||null; if(b) return Promise.resolve(b); }catch(e){}
    try{ if(window.amiyoGetBlob) return Promise.resolve(window.amiyoGetBlob(id)).catch(function(){ return null; }); }catch(e){}
    return Promise.resolve(null);
  }
  function probe(id){
    if(H[id]||busy[id]) return; busy[id]=1;
    blobOf(id).then(function(blob){
      if(!blob){ H[id]={ok:false,msg:"file missing on this device"}; done(id); return; }
      var url=URL.createObjectURL(blob), el=new Audio(), fin=false;
      function end(r){ if(fin) return; fin=true; try{ URL.revokeObjectURL(url); }catch(e){} H[id]=r; done(id); }
      el.preload="metadata";
      el.onloadedmetadata=function(){ end(el.duration>0||el.duration===Infinity?{ok:true,msg:"plays in this browser"}:{ok:false,msg:"no readable length"}); };
      el.onerror=function(){
        if(window.amiyoDecodeToWav){ window.amiyoDecodeToWav(blob).then(function(){ end({ok:true,msg:"plays (converted copy)"}); },function(){ end({ok:false,msg:"this browser cannot decode it"}); }); }
        else end({ok:false,msg:"this browser cannot decode it"});
      };
      setTimeout(function(){ end({ok:true,msg:"could not be tested"}); },8000);
      el.src=url;
    });
  }
  function done(id){ delete busy[id]; mark(); }
  function mark(){
    var lp=document.getElementById("leftPanel"); if(!lp) return;
    var l=lp.querySelectorAll("#auList [data-asset]");
    for(var i=0;i<l.length;i++){
      var id=l[i].getAttribute("data-asset"), row=l[i].closest(".au-row"); if(!row) continue;
      var nm=row.querySelector(".au-name"); if(!nm) continue;
      var h=H[id]; if(!h){ probe(id); continue; }
      var old=nm.querySelector(".au-imp"); if(!old){ old=document.createElement("i"); old.className="au-imp"; old.style.cssText="font-style:normal;font-size:10px"; nm.appendChild(old); }
      var t=(h.ok?"\u2713 ":"\u26a0 ")+h.msg; if(old.textContent!==t){ old.textContent=t; old.style.color=h.ok?"#3fb97a":"#e5984a"; }
    }
  }
  var lp=document.getElementById("leftPanel");
  if(lp){ var pend=0; new MutationObserver(function(){ if(pend) return; pend=1; setTimeout(function(){ pend=0; try{ mark(); }catch(e){ window.__swl&&window.__swl(e); } },60); }).observe(lp,{childList:true,subtree:true}); mark(); }
})();

