/* ==================== Script 806 id="amiyo-a07-heal-generated" ==================== */
/* Audio step 9: sort and length filter on sound effects. Audio step 8: library sounds draw their own waveform from their recipe. Audio step 7: a library sound or music bed on the timeline whose stored file is missing (cleared storage, reopened project) is rebuilt from its recipe, so it plays instead of staying silent. */
(function(){
  "use strict";
  var tried={};
  function defFor(a){
    var A=window.AMIYO_AUDIO; if(!A) return null;
    var nm=String(a.name||"").replace(/^(SFX|Music)\s*\u2014\s*/,"").replace(/\.wav$/i,"").toLowerCase();
    var pool=(A.sfx||[]).concat(A.beds||[]);
    for(var i=0;i<pool.length;i++){ if(pool[i]&&String(pool[i].name).toLowerCase()===nm) return pool[i]; }
    return null;
  }
  window.amiyoGeneratedDef=function(a){ try{ if(!a||a.type!=="audio"||!(a.tags||[]).some(function(t){ return t==="sfx"||t==="music"; })) return null; return defFor(a); }catch(e){ return null; } };
  function fix(a){
    var id=a.id; if(tried[id]) return; tried[id]=1;
    var have=null; try{ have=ASSET_BLOBS.get(id); }catch(e){}
    if(have){ return; }
    Promise.resolve(window.amiyoGetBlob?window.amiyoGetBlob(id):null).catch(function(){ return null; }).then(function(b){
      if(b){ try{ ASSET_BLOBS.set(id,b); }catch(e){} return; }
      var d=defFor(a); if(!d){ delete tried[id]; return; }
      try{
        var m=window.AMIYO_AUDIO.make(d); ASSET_BLOBS.set(id,m.blob);
        try{ if(ASSET_URLS&&ASSET_URLS.delete) ASSET_URLS.delete(id); }catch(e){}
        try{ if(window.amiyoPutBlob) window.amiyoPutBlob(id,m.blob); }catch(e){}
        try{ if(typeof renderAll==="function") renderAll(); }catch(e){}
      }catch(e){ window.__swl&&window.__swl(e); }
    });
  }
  function sweep(){
    try{
      if(typeof project==="undefined"||!project||!project.assets) return;
      for(var k in project.assets){ var a=project.assets[k]; if(a&&a.type==="audio"&&(a.tags||[]).some(function(t){ return t==="sfx"||t==="music"; })) fix(a); }
    }catch(e){ window.__swl&&window.__swl(e); }
  }
  setTimeout(sweep,2500); setInterval(sweep,6000);
  document.addEventListener("visibilitychange",function(){ if(!document.hidden) setTimeout(sweep,500); });
})();

