/* ==================== Script 807 id="amiyo-a09-sort-length" ==================== */
/* Audio step 9: sort the Sound effects list (original order, A\u2013Z, shortest, longest) and filter by length (any, under 1 s, 1\u20133 s, over 3 s). */
(function(){
  "use strict";
  var sort="def", len="any", obs=null;
  function secs(row){ var sp=row.querySelector(".au-name span"), m=sp&&/([\d.]+)\s*s\b/.exec(sp.textContent); return m?parseFloat(m[1]):0; }
  function nameOf(row){ var b=row.querySelector(".au-name b"); return b?b.textContent.toLowerCase():""; }
  function tab(){ var b=document.querySelector("#auTabs .chip.on"); return b?b.getAttribute("data-tab"):"sfx"; }
  function bar(){
    var tabs=document.getElementById("auTabs"); if(!tabs||document.getElementById("auSortBar")) return;
    var box=document.createElement("div"); box.id="auSortBar"; box.className="mini-row"; box.style.marginTop="8px";
    var h='<select id="auSortSel" class="search" aria-label="Sort sounds" style="max-width:150px"><option value="def">Sort: original</option><option value="az">Sort: A\u2013Z</option><option value="short">Sort: shortest</option><option value="long">Sort: longest</option></select>';
    [["any","Any length"],["s","< 1 s"],["m","1\u20133 s"],["l","> 3 s"]].forEach(function(x){ h+='<button type="button" class="chip" data-aln="'+x[0]+'">'+x[1]+'</button>'; });
    box.innerHTML=h; var after=document.getElementById("auXtra")||tabs; after.parentNode.insertBefore(box,after.nextSibling);
    box.querySelector("select").value=sort; mark();
  }
  function mark(){ var c=document.querySelectorAll("[data-aln]"); for(var i=0;i<c.length;i++) c[i].classList.toggle("on",c[i].getAttribute("data-aln")===len); }
  function apply(){
    var list=document.getElementById("auList"); if(!list) return;
    var box=document.getElementById("auSortBar"); if(box) box.style.display=tab()==="sfx"?"":"none";
    var rows=[].slice.call(list.querySelectorAll(".au-row")); if(!rows.length) return;
    rows.forEach(function(r,i){ if(r.getAttribute("data-ord")===null) r.setAttribute("data-ord",i); });
    if(tab()!=="sfx") return;
    var ord=rows.slice().sort(function(a,b){
      if(sort==="az") return nameOf(a)<nameOf(b)?-1:1;
      if(sort==="short") return secs(a)-secs(b)||a.getAttribute("data-ord")-b.getAttribute("data-ord");
      if(sort==="long") return secs(b)-secs(a)||a.getAttribute("data-ord")-b.getAttribute("data-ord");
      return a.getAttribute("data-ord")-b.getAttribute("data-ord");
    });
    var same=true; for(var i=0;i<rows.length;i++) if(rows[i]!==ord[i]){ same=false; break; }
    if(!same) ord.forEach(function(r){ list.appendChild(r); });
    var hide=0;
    rows.forEach(function(r){ var t=secs(r), ok=len==="any"||(len==="s"&&t<1)||(len==="m"&&t>=1&&t<=3)||(len==="l"&&t>3); r.setAttribute("data-lenhide",ok?"0":"1"); if(!ok) { r.style.display="none"; hide++; } else if(r.getAttribute("data-lenhide")==="0"&&r.style.display==="none"&&!r.getAttribute("data-favhide")) { /* leave other filters in charge */ } });
  }
  function poke(){ var l=document.getElementById("auList"); if(l){ var c=document.createComment(""); l.appendChild(c); l.removeChild(c); } }
  function run(){ bar(); apply(); if(obs) obs.takeRecords(); }
  var lp=document.getElementById("leftPanel"); if(!lp) return;
  var pend=0; obs=new MutationObserver(function(){ if(pend) return; pend=1; setTimeout(function(){ pend=0; try{ run(); }catch(e){ window.__swl&&window.__swl(e); } },20); });
  obs.observe(lp,{childList:true,subtree:true});
  lp.addEventListener("change",function(e){ if(e.target&&e.target.id==="auSortSel"){ sort=e.target.value; poke(); } });
  lp.addEventListener("click",function(e){ var b=e.target.closest&&e.target.closest("[data-aln]"); if(b){ len=b.getAttribute("data-aln"); mark(); poke(); } });
  run();
})();

