/* ==================== Script 814 id="amiyo-a16-report" ==================== */
/* Audio step 16: "Copy test report" runs the full sound check (silence, broken samples, clipping, repeated ids/names, length) and copies a plain-text report. */
(function(){
  "use strict";
  var lp=document.getElementById("leftPanel"), running=false; if(!lp) return;
  function testOne(d,pool){
    var bad=[];
    try{
      var f=d.gen(), pk=0, sq=0, nan=0, v;
      for(var i=0;i<f.length;i++){ v=f[i]; if(v!==v||v===Infinity||v===-Infinity){ nan++; continue; } if(v<0) v=-v; if(v>pk) pk=v; sq+=v*v; }
      if(!f.length) bad.push("empty"); if(nan) bad.push("broken samples"); if(pk<.02||Math.sqrt(sq/Math.max(1,f.length))<.003) bad.push("silent"); if(pk>1.001) bad.push("clips"); if(f.length/44100<.05) bad.push("too short");
    }catch(e){ bad.push("fails to render: "+((e&&e.message)||e)); }
    var same=0,sn=0; for(var k=0;k<pool.length;k++){ if(pool[k].id===d.id) same++; if(String(pool[k].name).toLowerCase()===String(d.name).toLowerCase()) sn++; }
    if(same>1) bad.push("id shared"); if(sn>1) bad.push("name repeated");
    return bad;
  }
  function ui(){
    var chk=document.getElementById("auCheck"); if(!chk||document.getElementById("auReport")) return;
    var b=document.createElement("button"); b.type="button"; b.className="chip"; b.id="auReport"; b.textContent="Copy test report"; chk.parentNode.insertBefore(b,chk.nextSibling);
  }
  function run(btn){
    if(running) return; running=true; var A=window.AMIYO_AUDIO; if(!A){ running=false; return; }
    var pool=[].concat(A.sfx||[],A.beds||[]).filter(Boolean), i=0, lines=[], bad=0, out=document.getElementById("auCheckOut");
    btn.disabled=true;
    (function step(){
      var t=Date.now();
      while(i<pool.length&&Date.now()-t<40){ var r=testOne(pool[i],pool); if(r.length){ bad++; lines.push("- "+pool[i].name+" ("+pool[i].id+"): "+r.join(", ")); } i++; }
      if(out) out.textContent="Testing "+i+" of "+pool.length+"\u2026";
      if(i<pool.length){ setTimeout(step,0); return; }
      var txt="Amiyo audio test: "+pool.length+" sounds checked, "+bad+" with problems"+(bad?"\n"+lines.join("\n"):"");
      if(out) out.textContent=bad?bad+" need attention":"All "+pool.length+" sounds are fine";
      try{ navigator.clipboard.writeText(txt).then(function(){ window.toast&&window.toast("Report copied"); },function(){ window.toast&&window.toast(txt.split("\n")[0]); }); }catch(e){ window.toast&&window.toast(txt.split("\n")[0]); }
      btn.disabled=false; running=false;
    })();
  }
  new MutationObserver(function(){ ui(); }).observe(lp,{childList:true,subtree:true});
  lp.addEventListener("click",function(e){ var b=e.target.closest&&e.target.closest("#auReport"); if(b){ e.preventDefault(); run(b); } },true);
  ui();
})();

