/* ==================== Script 817 id="amiyo-a20-timeline-audio-check" ==================== */
/* Audio round 2: "Check timeline audio" lists every reason an audio clip could be silent: missing asset or file, unreadable length, muted/hidden track, clip switched off, volume 0, speed too slow, start point past the end of the file. Tap an item to jump to the clip. Read-only: it changes nothing. */
(function(){
  "use strict";
  var lp=document.getElementById("leftPanel"); if(!lp) return;
  function blobHas(id){
    try{ if(ASSET_BLOBS.get(id)) return Promise.resolve(true); }catch(e){}
    try{ if(window.amiyoGetBlob) return Promise.resolve(window.amiyoGetBlob(id)).then(function(b){ return !!b; },function(){ return false; }); }catch(e){}
    return Promise.resolve(true);
  }
  function scan(){
    var jobs=[], out=[];
    project.tracks.forEach(function(t){
      if(t.kind!=="audio"&&t.kind!=="video") return;
      t.clips.forEach(function(c){
        var a=project.assets[c.assetId], nm=c.name||(a&&a.name)||"Clip", w=[];
        if(t.kind==="video"&&!(a&&a.type==="video")) return;
        if(!a){ out.push({c:c,t:t,msg:nm+": its file is not in this project"}); return; }
        if(t.kind==="audio"){
          if(t.muted) w.push("track is muted"); if(t.hidden) w.push("track is hidden"); if(c.off) w.push("clip is switched off");
          if((c.volume!=null&&+c.volume<=0)) w.push("volume is 0"); if(c.volume!=null&&!isFinite(+c.volume)) w.push("volume is invalid");
          if((c.speed||1)<.0625) w.push("speed is too slow to play");
          if(a.duration>0&&(c.inPoint||0)>=a.duration-.01) w.push("start point is past the end of the file");
          if(!(a.duration>0)) w.push("file length unknown");
        }
        if(w.length) out.push({c:c,t:t,msg:nm+": "+w.join(", ")});
        if(t.kind==="audio") jobs.push(blobHas(a.id).then(function(ok){ if(!ok) out.push({c:c,t:t,msg:nm+": file data missing on this device (import again)"}); }));
      });
    });
    return Promise.all(jobs).then(function(){ return out; });
  }
  function show(list){
    var box=document.getElementById("auTlOut"); if(!box) return;
    if(!list.length){ box.innerHTML='<div style="font-size:11px;color:#3fb97a;margin-top:6px">\u2713 No silent-audio problems found on the timeline.</div>'; return; }
    box.innerHTML='<div style="font-size:11px;color:#e5984a;margin-top:6px">'+list.length+' thing'+(list.length>1?'s':'')+' to look at (tap to jump):</div>'+list.slice(0,40).map(function(x,i){ return '<button type="button" class="chip" data-tlj="'+i+'" style="display:block;text-align:left;margin-top:4px;white-space:normal">\u26a0 '+String(x.msg).replace(/[&<>"]/g,function(m){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m]; })+'</button>'; }).join("");
    box._list=list;
  }
  function ui(){
    var tabs=document.getElementById("auTabs"); if(!tabs||document.getElementById("auTlCheck")) return;
    var d=document.createElement("div"); d.style.marginTop="8px"; d.innerHTML='<button type="button" class="chip" id="auTlCheck">Check timeline audio</button><div id="auTlOut" role="status"></div>';
    var card=tabs.parentNode; card.appendChild(d);
  }
  new MutationObserver(function(){ ui(); }).observe(lp,{childList:true,subtree:true});
  lp.addEventListener("click",function(e){
    var b=e.target.closest&&e.target.closest("#auTlCheck");
    if(b){ e.preventDefault(); b.disabled=true; scan().then(show).catch(function(x){ window.__swl&&window.__swl(x); }).then(function(){ b.disabled=false; }); return; }
    var j=e.target.closest&&e.target.closest("[data-tlj]"); if(!j) return; e.preventDefault();
    var box=document.getElementById("auTlOut"), it=box&&box._list&&box._list[+j.getAttribute("data-tlj")]; if(!it) return;
    try{ selectedClipId=it.c.id; selectedTrackId=it.t.id; currentTime=Math.max(0,it.c.start); if(typeof renderAll==="function") renderAll(); }catch(x){ window.__swl&&window.__swl(x); }
  },true);
  ui();
})();

