/* ==================== Script 849 id="amiyo-snd13" ==================== */
(function(){
function reg(l,f){ if(window.__amSound) window.__amSound.add(l,f); else (window.__amSoundQ=window.__amSoundQ||[]).push([l,f]); }
function audioClips(){var a=[];project.tracks.forEach(function(t){if(t.kind==="audio")t.clips.forEach(function(c){a.push({t:t,c:c});});});return a;}
function db(x){return x>1e-6?20*Math.log10(x):-120;}
function f1(x){return (Math.round(x*10)/10).toFixed(1);}
function sel(){var f=getClip();if(!f)throw new Error("Select an audio clip first");if(!f.clip.assetId)throw new Error("This clip has no audio media");return f;}
/* Sound step 13: stereo check. Tells you if the selected clip is real stereo, or the same signal on both sides (mono in disguise). */
reg("Stereo check",async function(){var f=sel(),m=await window.__amMono(f.clip),b=m.buf;if(b.numberOfChannels<2)return "Mono file (1 channel).";
 var L=b.getChannelData(0),R=b.getChannelData(1),i0=Math.floor((f.clip.inPoint||0)*b.sampleRate),n=Math.min(m.d.length,200000),diff=0,tot=0;
 for(var i=0;i<n;i++){var l=L[i0+i],r=R[i0+i];diff+=Math.abs(l-r);tot+=Math.abs(l)+Math.abs(r);}
 var ratio=tot?diff/tot:0;return ratio<0.01?"Both channels are identical: this is mono stored as stereo.":"True stereo. Left/right difference "+Math.round(ratio*100)+"%.";});
})();
